(window.BBD=window.BBD||{});BBD["رومية"]=[["بولس عبد ليسوع المسيح المدعو رسولا المفرز لإنجيل االله","الذي سبق فوعد به بأنبيائه في الكتب المقدسة","عن ابنه. الذي صار من نسل داود من جهة الجسد","وتعين ابن االله بقوة من جهة روح القداسة بالقيامة من الأموات: يسوع المسيح ربنا.","الذي به لأجل اسمه قبلنا نعمة ورسالة لإطاعة الإيمان في جميع الأمم","الذين بينهم أنتم أيضا مدعوو يسوع المسيح.","إلى جميع الموجودين في رومية أحباء االله مدعوين قديسين: نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","أولا أشكر إلهي بيسوع المسيح من جهة جميعكم أن إيمانكم ينادى به في كل العالم.","فإن االله الذي أعبده بروحي في إنجيل ابنه شاهد لي كيف بلا انقطاع أذكركم","متضرعا دائما في صلواتي عسى الآن أن يتيسر لي مرة بمشيئة االله أن آتي إليكم.","لأني مشتاق أن أراكم لكي أمنحكم هبة روحية لثباتكم","أي لنتعزى بينكم بالإيمان الذي فينا جميعا إيمانكم وإيماني.","ثم لست أريد أن تجهلوا أيها الإخوة أنني مرارا كثيرة قصدت أن آتي إليكم ومنعت حتى الآن ليكون لي ثمر فيكم أيضا كما في سائر الأمم.","إني مديون لليونانيين والبرابرة للحكماء والجهلاء.","فهكذا ما هو لي مستعد لتبشيركم أنتم الذين في رومية أيضا","لأني لست أستحي بإنجيل المسيح لأنه قوة االله للخلاص لكل من يؤمن: لليهودي أولا ثم لليوناني.","لأن فيه معلن بر االله بإيمان لإيمان كما هو مكتوب»أما البار فبالإيمان يحيا«.","لأن غضب االله معلن من السماء على جميع فجور الناس وإثمهم الذين يحجزون الحق بالإثم.","إذ معرفة االله ظاهرة فيهم لأن االله أظهرها لهم","لأن منذ خلق العالم ترى أموره غير المنظورة وقدرته السرمدية ولاهوته مدركة بالمصنوعات حتى إنهم بلا عذر.","لأنهم لما عرفوا االله لم يمجدوه أو يشكروه كإله بل حمقوا في أفكارهم وأظلم قلبهم الغبي.","وبينما هم يزعمون أنهم حكماء صاروا جهلاء","وأبدلوا مجد االله الذي لا يفنى بشبه صورة الإنسان الذي يفنى والطيور والدواب والزحافات.","لذلك أسلمهم االله أيضا في شهوات قلوبهم إلى النجاسة لإهانة أجسادهم بين ذواتهم.","الذين استبدلوا حق االله بالكذب واتقوا وعبدوا المخلوق دون الخالق الذي هو مبارك إلى الأبد. آمين.","لذلك أسلمهم االله إلى أهواء الهوان لأن إناثهم استبدلن الاستعمال الطبيعي بالذي على خلاف الطبيعة","وكذلك الذكور أيضا تاركين استعمال الأنثى الطبيعي اشتعلوا بشهوتهم بعضهم لبعض فاعلين الفحشاء ذكورا بذكور ونائلين في أنفسهم جزاء ضلالهم المحق.","وكما لم يستحسنوا أن يبقوا االله في معرفتهم أسلمهم االله إلى ذهن مرفوض ليفعلوا ما لا يليق.","مملوئين من كل إثم وزنا وشر وطمع وخبث مشحونين حسدا وقتلا وخصاما ومكرا وسوءا","نمامين مفترين مبغضين لله ثالبين متعظمين مدعين مبتدعين شرورا غير طائعين للوالدين","بلا فهم ولا عهد ولا حنو ولا رضى ولا رحمة.","الذين إذ عرفوا حكم االله أن الذين يعملون مثل هذه يستوجبون الموت لا يفعلونها فقط بل أيضا يسرون بالذين يعملون!"],["لذلك أنت بلا عذر أيها الإنسان كل من يدين. لأنك في ما تدين غيرك تحكم على نفسك. لأنك أنت الذي تدين تفعل تلك الأمور بعينها!","ونحن نعلم أن دينونة االله هي حسب الحق على الذين يفعلون مثل هذه.","أفتظن هذا أيها الإنسان الذي تدين الذين يفعلون مثل هذه وأنت تفعلها أنك تنجو من دينونة االله؟","أم تستهين بغنى لطفه وإمهاله وطول أناته غير عالم أن لطف االله إنما يقتادك إلى التوبة؟","ولكنك من أجل قساوتك وقلبك غير التائب تذخر لنفسك غضبا في يوم الغضب واستعلان دينونة االله العادلة","الذي سيجازي كل واحد حسب أعماله.","أما الذين بصبر في العمل الصالح يطلبون المجد والكرامة والبقاء فبالحياة الأبدية.","وأما الذين هم من أهل التحزب ولا يطاوعون للحق بل يطاوعون للإثم فسخط وغضب","شدة وضيق على كل نفس إنسان يفعل الشر اليهودي أولا ثم اليوناني.","ومجد وكرامة وسلام لكل من يفعل الصلاح اليهودي أولا ثم اليوناني.","لأن ليس عند االله محاباة.","لأن كل من أخطأ بدون الناموس فبدون الناموس يهلك وكل من أخطأ في الناموس فبالناموس يدان.","لأن ليس الذين يسمعون الناموس هم أبرار عند االله بل الذين يعملون بالناموس هم يبررون.","لأنه الأمم الذين ليس عندهم الناموس متى فعلوا بالطبيعة ما هو في الناموس فهؤلاء إذ ليس لهم الناموس هم ناموس لأنفسهم","الذين يظهرون عمل الناموس مكتوبا في قلوبهم شاهدا أيضا ضميرهم وأفكارهم فيما بينها مشتكية أو محتجة","في اليوم الذي فيه يدين االله سرائر الناس حسب إنجيلي بيسوع المسيح.","هوذا أنت تسمى يهوديا وتتكل على الناموس وتفتخر بالله","وتعرف مشيئته وتميز الأمور المتخالفة متعلما من الناموس.","وتثق أنك قائد للعميان ونور للذين في الظلمة","ومهذب للأغبياء ومعلم للأطفال ولك صورة العلم والحق في الناموس.","فأنت إذا الذي تعلم غيرك ألست تعلم نفسك؟ الذي تكرز أن لا يسرق أتسرق؟","الذي تقول أن لا يزنى أتزني؟ الذي تستكره الأوثان أتسرق الهياكل؟","الذي تفتخر بالناموس أبتعدي الناموس تهين االله؟","لأن اسم االله يجدف عليه بسببكم بين الأمم كما هو مكتوب.","فإن الختان ينفع إن عملت بالناموس. ولكن إن كنت متعديا الناموس فقد صار ختانك غرلة!","إذا إن كان الأغرل يحفظ أحكام الناموس أفما تحسب غرلته ختانا؟","وتكون الغرلة التي من الطبيعة وهي تكمل الناموس تدينك أنت الذي في الكتاب والختان تتعدى الناموس؟","لأن اليهودي في الظاهر ليس هو يهوديا ولا الختان الذي في الظاهر في اللحم ختانا","بل اليهودي في الخفاء هو اليهودي وختان القلب بالروح لا بالكتاب هو الختان الذي مدحه ليس من الناس بل من االله."],["إذا ما هو فضل اليهودي أو ما هو نفع الختان؟","كثير على كل وجه! أما أولا فلأنهم استؤمنوا على أقوال االله.","فماذا إن كان قوم لم يكونوا أمناء؟ أفلعل عدم أمانتهم يبطل أمانة االله؟","حاشا! بل ليكن االله صادقا وكل إنسان كاذبا. كما هو مكتوب: »لكي تتبرر في كلامك وتغلب متى حوكمت«.","ولكن إن كان إثمنا يبين بر االله فماذا نقول؟ ألعل االله الذي يجلب الغضب ظالم؟ أتكلم بحسب الإنسان.","حاشا! فكيف يدين االله العالم إذ ذاك؟","فإنه إن كان صدق االله قد ازداد بكذبي لمجده فلماذا أدان أنا بعد كخاطئ؟","أما كما يفترى علينا وكما يزعم قوم أننا نقول: »لنفعل السيآت لكي تأتي الخيرات«. الذين دينونتهم عادلة.","فماذا إذا؟ أنحن أفضل؟ كلا البتة! لأننا قد شكونا أن اليهود واليونانيين أجمعين تحت الخطية","كما هو مكتوب: »أنه ليس بار ولا واحد.","ليس من يفهم. ليس من يطلب االله.","الجميع زاغوا وفسدوا معا. ليس من يعمل صلاحا ليس ولا واحد.","حنجرتهم قبر مفتوح. بألسنتهم قد مكروا. سم الأصلال تحت شفاههم.","وفمهم مملوء لعنة ومرارة.","أرجلهم سريعة إلى سفك الدم.","في طرقهم اغتصاب وسحق.","وطريق السلام لم يعرفوه.","ليس خوف االله قدام عيونهم«.","ونحن نعلم أن كل ما يقوله الناموس فهو يكلم به الذين في الناموس لكي يستد كل فم ويصير كل العالم تحت قصاص من االله.","لأنه بأعمال الناموس كل ذي جسد لا يتبرر أمامه. لأن بالناموس معرفة الخطية.","وأما الآن فقد ظهر بر االله بدون الناموس مشهودا له من الناموس والأنبياء","بر االله بالإيمان بيسوع المسيح إلى كل وعلى كل الذين يؤمنون. لأنه لا فرق.","إذ الجميع أخطأوا وأعوزهم مجد االله","متبررين مجانا بنعمته بالفداء الذي بيسوع المسيح","الذي قدمه االله كفارة بالإيمان بدمه لإظهار بره من أجل الصفح عن الخطايا السالفة بإمهال االله.","لإظهار بره في الزمان الحاضر ليكون بارا ويبرر من هو من الإيمان بيسوع.","فأين الافتخار؟ قد انتفى! بأي ناموس؟ أبناموس الأعمال؟ كلا! بل بناموس الإيمان.","إذا نحسب أن الإنسان يتبرر بالإيمان بدون أعمال الناموس.","أم االله لليهود فقط؟ أليس للأمم أيضا؟ بلى للأمم أيضا؟","لأن االله واحد هو الذي سيبرر الختان بالإيمان والغرلة بالإيمان.","أفنبطل الناموس بالإيمان؟ حاشا! بل نثبت الناموس."],["فماذا نقول إن أبانا إبراهيم قد وجد حسب الجسد؟","لأنه إن كان إبراهيم قد تبرر بالأعمال فله فخر - ولكن ليس لدى االله.","لأنه ماذا يقول الكتاب؟ »فآمن إبراهيم بالله فحسب له برا«.","أما الذي يعمل فلا تحسب له الأجرة على سبيل نعمة بل على سبيل دين.","وأما الذي لا يعمل ولكن يؤمن بالذي يبرر الفاجر فإيمانه يحسب له برا.","كما يقول داود أيضا في تطويب الإنسان الذي يحسب له االله برا بدون أعمال:","»طوبى للذين غفرت آثامهم وسترت خطاياهم.","طوبى للرجل الذي لا يحسب له الرب خطية«.","أفهذا التطويب هو على الختان فقط أم على الغرلة أيضا؟ لأننا نقول إنه حسب لإبراهيم الإيمان برا.","فكيف حسب؟ أوهو في الختان أم في الغرلة؟ ليس في الختان بل في الغرلة!","وأخذ علامة الختان ختما لبر الإيمان الذي كان في الغرلة ليكون أبا لجميع الذين يؤمنون وهم في الغرلة كي يحسب لهم أيضا البر.","وأبا للختان للذين ليسوا من الختان فقط بل أيضا يسلكون في خطوات إيمان أبينا إبراهيم الذي كان وهو في الغرلة.","فإنه ليس بالناموس كان الوعد لإبراهيم أو لنسله أن يكون وارثا للعالم بل ببر الإيمان.","لأنه إن كان الذين من الناموس هم ورثة فقد تعطل الإيمان وبطل الوعد!","لأن الناموس ينشئ غضبا إذ حيث ليس ناموس ليس أيضا تعد.","لهذا هو من الإيمان كي يكون على سبيل النعمة ليكون الوعد وطيدا لجميع النسل. ليس لمن هو من الناموس فقط بل أيضا لمن هو من إيمان إبراهيم الذي هو أب لجميعنا.","كما هو مكتوب: »إني قد جعلتك أبا لأمم كثيرة«. أمام االله الذي آمن به الذي يحيي الموتى ويدعو الأشياء غير الموجودة كأنها موجودة.","فهو على خلاف الرجاء آمن على الرجاء لكي يصير أبا لأمم كثيرة كما قيل: »هكذا يكون نسلك«.","وإذ لم يكن ضعيفا في الإيمان لم يعتبر جسده - وهو قد صار مماتا إذ كان ابن نحو مئة سنة - ولا مماتية مستودع سارة.","ولا بعدم إيمان ارتاب في وعد االله بل تقوى بالإيمان معطيا مجدا لله.","وتيقن أن ما وعد به هو قادر أن يفعله أيضا.","لذلك أيضا حسب له برا.","ولكن لم يكتب من أجله وحده أنه حسب له","بل من أجلنا نحن أيضا الذين سيحسب لنا الذين نؤمن بمن أقام يسوع ربنا من الأموات.","الذي أسلم من أجل خطايانا وأقيم لأجل تبريرنا."],["فإذ قد تبررنا بالإيمان لنا سلام مع االله بربنا يسوع المسيح","الذي به أيضا قد صار لنا الدخول بالإيمان إلى هذه النعمة التي نحن فيها مقيمون ونفتخر على رجاء مجد االله.","وليس ذلك فقط بل نفتخر أيضا في الضيقات عالمين أن الضيق ينشئ صبرا","والصبر تزكية والتزكية رجاء","والرجاء لا يخزي لأن محبة االله قد انسكبت في قلوبنا بالروح القدس المعطى لنا.","لأن المسيح إذ كنا بعد ضعفاء مات في الوقت المعين لأجل الفجار.","فإنه بالجهد يموت أحد لأجل بار. ربما لأجل الصالح يجسر أحد أيضا أن يموت.","ولكن االله بين محبته لنا لأنه ونحن بعد خطاة مات المسيح لأجلنا.","فبالأولى كثيرا ونحن متبررون الآن بدمه نخلص به من الغضب.","لأنه إن كنا ونحن أعداء قد صولحنا مع االله بموت ابنه فبالأولى كثيرا ونحن مصالحون نخلص بحياته.","وليس ذلك فقط بل نفتخر أيضا بالله بربنا يسوع المسيح الذي نلنا به الآن المصالحة.","من أجل ذلك كأنما بإنسان واحد دخلت الخطية إلى العالم وبالخطية الموت وهكذا اجتاز الموت إلى جميع الناس إذ أخطأ الجميع.","فإنه حتى الناموس كانت الخطية في العالم. على أن الخطية لا تحسب إن لم يكن ناموس.","لكن قد ملك الموت من آدم إلى موسى وذلك على الذين لم يخطئوا على شبه تعدي آدم الذي هو مثال الآتي.","ولكن ليس كالخطية هكذا أيضا الهبة. لأنه إن كان بخطية واحد مات الكثيرون فبالأولى كثيرا نعمة االله والعطية بالنعمة التي بالإنسان الواحد يسوع المسيح قد ازدادت للكثيرين.","وليس كما بواحد قد أخطأ هكذا العطية. لأن الحكم من واحد للدينونة وأما الهبة فمن جرى خطايا كثيرة للتبرير.","لأنه إن كان بخطية الواحد قد ملك الموت بالواحد فبالأولى كثيرا الذين ينالون فيض النعمة وعطية البر سيملكون في الحياة بالواحد يسوع المسيح.","فإذا كما بخطية واحدة صار الحكم إلى جميع الناس للدينونة هكذا ببر واحد صارت الهبة إلى جميع الناس لتبرير الحياة.","لأنه كما بمعصية الإنسان الواحد جعل الكثيرون خطاة هكذا أيضا بإطاعة الواحد سيجعل الكثيرون أبرارا.","وأما الناموس فدخل لكي تكثر الخطية. ولكن حيث كثرت الخطية ازدادت النعمة جدا.","حتى كما ملكت الخطية في الموت هكذا تملك النعمة بالبر للحياة الأبدية بيسوع المسيح ربنا."],["فماذا نقول؟ أنبقى في الخطية لكي تكثر النعمة؟","حاشا! نحن الذين متنا عن الخطية كيف نعيش بعد فيها؟","أم تجهلون أننا كل من اعتمد ليسوع المسيح اعتمدنا لموته","فدفنا معه بالمعمودية للموت حتى كما أقيم المسيح من الأموات بمجد الآب هكذا نسلك نحن أيضا في جدة الحياة.","لأنه إن كنا قد صرنا متحدين معه بشبه موته نصير أيضا بقيامته.","عالمين هذا: أن إنساننا العتيق قد صلب معه ليبطل جسد الخطية كي لا نعود نستعبد أيضا للخطية.","لأن الذي مات قد تبرأ من الخطية.","فإن كنا قد متنا مع المسيح نؤمن أننا سنحيا أيضا معه.","عالمين أن المسيح بعدما أقيم من الأموات لا يموت أيضا. لا يسود عليه الموت بعد.","لأن الموت الذي ماته قد ماته للخطية مرة واحدة والحياة التي يحياها فيحياها لله.","كذلك أنتم أيضا احسبوا أنفسكم أمواتا عن الخطية ولكن أحياء لله بالمسيح يسوع ربنا.","إذا لا تملكن الخطية في جسدكم المائت لكي تطيعوها في شهواته","ولا تقدموا أعضاءكم آلات إثم للخطية بل قدموا ذواتكم لله كأحياء من الأموات وأعضاءكم آلات بر لله.","فإن الخطية لن تسودكم لأنكم لستم تحت الناموس بل تحت النعمة.","فماذا إذا؟ أنخطئ لأننا لسنا تحت الناموس بل تحت النعمة؟ حاشا!","ألستم تعلمون أن الذي تقدمون ذواتكم له عبيدا للطاعة أنتم عبيد للذي تطيعونه إما للخطية للموت أو للطاعة للبر؟","فشكرا لله أنكم كنتم عبيدا للخطية ولكنكم أطعتم من القلب صورة التعليم التي تسلمتموها.","وإذ أعتقتم من الخطية صرتم عبيدا للبر.","أتكلم إنسانيا من أجل ضعف جسدكم. لأنه كما قدمتم أعضاءكم عبيدا للنجاسة والإثم للإثم هكذا الآن قدموا أعضاءكم عبيدا للبر للقداسة.","لأنكم لما كنتم عبيد الخطية كنتم أحرارا من البر.","فأي ثمر كان لكم حينئذ من الأمور التي تستحون بها الآن؟ لأن نهاية تلك الأمور هي الموت.","وأما الآن إذ أعتقتم من الخطية وصرتم عبيدا لله فلكم ثمركم للقداسة والنهاية حياة أبدية.","لأن أجرة الخطية هي موت وأما هبة االله فهي حياة أبدية بالمسيح يسوع ربنا."],["أم تجهلون أيها الإخوة - لأني أكلم العارفين بالناموس - أن الناموس يسود على الإنسان ما دام حيا.","فإن المرأة التي تحت رجل هي مرتبطة بالناموس بالرجل الحي. ولكن إن مات الرجل فقد تحررت من ناموس الرجل.","فإذا ما دام الرجل حيا تدعى زانية إن صارت لرجل آخر. ولكن إن مات الرجل فهي حرة من الناموس حتى إنها ليست زانية إن صارت لرجل آخر.","إذا يا إخوتي أنتم أيضا قد متم للناموس بجسد المسيح لكي تصيروا لآخر للذي قد أقيم من الأموات لنثمر لله.","لأنه لما كنا في الجسد كانت أهواء الخطايا التي بالناموس تعمل في أعضائنا لكي نثمر للموت.","وأما الآن فقد تحررنا من الناموس إذ مات الذي كنا ممسكين فيه حتى نعبد بجدة الروح لا بعتق الحرف.","فماذا نقول؟ هل الناموس خطية؟ حاشا! بل لم أعرف الخطية إلا بالناموس. فإنني لم أعرف الشهوة لو لم يقل الناموس »لا تشته«.","ولكن الخطية وهي متخذة فرصة بالوصية أنشأت في كل شهوة. لأن بدون الناموس الخطية ميتة.","أما أنا فكنت بدون الناموس عائشا قبلا. ولكن لما جاءت الوصية عاشت الخطية فمت أنا","فوجدت الوصية التي للحياة هي نفسها لي للموت.","لأن الخطية وهي متخذة فرصة بالوصية خدعتني بها وقتلتني.","إذا الناموس مقدس والوصية مقدسة وعادلة وصالحة.","فهل صار لي الصالح موتا؟ حاشا! بل الخطية. لكي تظهر خطية منشئة لي بالصالح موتا لكي تصير الخطية خاطئة جدا بالوصية.","فإننا نعلم أن الناموس روحي وأما أنا فجسدي مبيع تحت الخطية.","لأني لست أعرف ما أنا أفعله إذ لست أفعل ما أريده بل ما أبغضه فإياه أفعل.","فإن كنت أفعل ما لست أريده فإني أصادق الناموس أنه حسن.","فالآن لست بعد أفعل ذلك أنا بل الخطية الساكنة في.","فإني أعلم أنه ليس ساكن في أي في جسدي شيء صالح. لأن الإرادة حاضرة عندي وأما أن أفعل الحسنى فلست أجد.","لأني لست أفعل الصالح الذي أريده بل الشر الذي لست أريده فإياه أفعل.","فإن كنت ما لست أريده إياه أفعل فلست بعد أفعله أنا بل الخطية الساكنة في.","إذا أجد الناموس لي حينما أريد أن أفعل الحسنى أن الشر حاضر عندي.","فإني أسر بناموس االله بحسب الإنسان الباطن.","ولكني أرى ناموسا آخر في أعضائي يحارب ناموس ذهني ويسبيني إلى ناموس الخطية الكائن في أعضائي.","ويحي أنا الإنسان الشقي! من ينقذني من جسد هذا الموت؟","أشكر االله بيسوع المسيح ربنا! إذا أنا نفسي بذهني أخدم ناموس االله ولكن بالجسد ناموس الخطية."],["إذا لا شيء من الدينونة الآن على الذين هم في المسيح يسوع السالكين ليس حسب الجسد بل حسب الروح.","لأن ناموس روح الحياة في المسيح يسوع قد أعتقني من ناموس الخطية والموت.","لأنه ما كان الناموس عاجزا عنه في ما كان ضعيفا بالجسد فالله إذ أرسل ابنه في شبه جسد الخطية ولأجل الخطية دان الخطية في الجسد","لكي يتم حكم الناموس فينا نحن السالكين ليس حسب الجسد بل حسب الروح.","فإن الذين هم حسب الجسد فبما للجسد يهتمون ولكن الذين حسب الروح فبما للروح.","لأن اهتمام الجسد هو موت ولكن اهتمام الروح هو حياة وسلام.","لأن اهتمام الجسد هو عداوة لله إذ ليس هو خاضعا لناموس االله لأنه أيضا لا يستطيع.","فالذين هم في الجسد لا يستطيعون أن يرضوا االله.","وأما أنتم فلستم في الجسد بل في الروح إن كان روح االله ساكنا فيكم. ولكن إن كان أحد ليس له روح المسيح فذلك ليس له.","وإن كان المسيح فيكم فالجسد ميت بسبب الخطية وأما الروح فحياة بسبب البر.","وإن كان روح الذي أقام يسوع من الأموات ساكنا فيكم فالذي أقام المسيح من الأموات سيحيي أجسادكم المائتة أيضا بروحه الساكن فيكم.","فإذا أيها الإخوة نحن مديونون ليس للجسد لنعيش حسب الجسد.","لأنه إن عشتم حسب الجسد فستموتون ولكن إن كنتم بالروح تميتون أعمال الجسد فستحيون.","لأن كل الذين ينقادون بروح االله فأولئك هم أبناء االله.","إذ لم تأخذوا روح العبودية أيضا للخوف بل أخذتم روح التبني الذي به نصرخ: »يا أبا الآب!«.","الروح نفسه أيضا يشهد لأرواحنا أننا أولاد االله.","فإن كنا أولادا فإننا ورثة أيضا ورثة االله ووارثون مع المسيح. إن كنا نتألم معه لكي نتمجد أيضا معه.","فإني أحسب أن آلام الزمان الحاضر لا تقاس بالمجد العتيد أن يستعلن فينا.","لأن انتظار الخليقة يتوقع استعلان أبناء االله.","إذ أخضعت الخليقة للبطل - ليس طوعا بل من أجل الذي أخضعها - على الرجاء.","لأن الخليقة نفسها أيضا ستعتق من عبودية الفساد إلى حرية مجد أولاد االله.","فإننا نعلم أن كل الخليقة تئن وتتمخض معا إلى الآن.","وليس هكذا فقط بل نحن الذين لنا باكورة الروح نحن أنفسنا أيضا نئن في أنفسنا متوقعين التبني فداء أجسادنا.","لأننا بالرجاء خلصنا. ولكن الرجاء المنظور ليس رجاء لأن ما ينظره أحد كيف يرجوه أيضا؟","ولكن إن كنا نرجو ما لسنا ننظره فإننا نتوقعه بالصبر.","وكذلك الروح أيضا يعين ضعفاتنا لأننا لسنا نعلم ما نصلي لأجله كما ينبغي. ولكن الروح نفسه يشفع فينا بأنات لا ينطق بها.","ولكن الذي يفحص القلوب يعلم ما هو اهتمام الروح لأنه بحسب مشيئة االله يشفع في القديسين.","ونحن نعلم أن كل الأشياء تعمل معا للخير للذين يحبون االله الذين هم مدعوون حسب قصده.","لأن الذين سبق فعرفهم سبق فعينهم ليكونوا مشابهين صورة ابنه ليكون هو بكرا بين إخوة كثيرين.","والذين سبق فعينهم فهؤلاء دعاهم أيضا. والذين دعاهم فهؤلاء بررهم أيضا. والذين بررهم فهؤلاء مجدهم أيضا.","فماذا نقول لهذا؟ إن كان االله معنا فمن علينا!","الذي لم يشفق على ابنه بل بذله لأجلنا أجمعين كيف لا يهبنا أيضا معه كل شيء؟","من سيشتكي على مختاري االله؟ الله هو الذي يبرر!","من هو الذي يدين؟ المسيح هو الذي مات بل بالحري قام أيضا الذي هو أيضا عن يمين االله الذي أيضا يشفع فينا!","من سيفصلنا عن محبة المسيح؟ أشدة أم ضيق أم اضطهاد أم جوع أم عري أم خطر أم سيف؟","كما هو مكتوب »إننا من أجلك نمات كل النهار. قد حسبنا مثل غنم للذبح«.","ولكننا في هذه جميعها يعظم انتصارنا بالذي أحبنا.","فإني متيقن أنه لا موت ولا حياة ولا ملائكة ولا رؤساء ولا قوات ولا أمور حاضرة ولا مستقبلة","ولا علو ولا عمق ولا خليقة أخرى تقدر أن تفصلنا عن محبة االله التي في المسيح يسوع ربنا."],["أقول الصدق في المسيح لا أكذب وضميري شاهد لي بالروح القدس:","إن لي حزنا عظيما ووجعا في قلبي لا ينقطع!","فإني كنت أود لو أكون أنا نفسي محروما من المسيح لأجل إخوتي أنسبائي حسب الجسد","الذين هم إسرائيليون ولهم التبني والمجد والعهود والاشتراع والعبادة والمواعيد","ولهم الآباء ومنهم المسيح حسب الجسد الكائن على الكل إلها مباركا إلى الأبد. آمين.","ولكن ليس هكذا حتى إن كلمة االله قد سقطت. لأن ليس جميع الذين من إسرائيل هم إسرائيليون","ولا لأنهم من نسل إبراهيم هم جميعا أولاد. بل »بإسحاق يدعى لك نسل«.","أي ليس أولاد الجسد هم أولاد االله بل أولاد الموعد يحسبون نسلا.","لأن كلمة الموعد هي هذه: »أنا آتي نحو هذا الوقت ويكون لسارة ابن«.","وليس ذلك فقط بل رفقة أيضا وهي حبلى من واحد وهو إسحاق أبونا -","لأنه وهما لم يولدا بعد ولا فعلا خيرا أو شرا لكي يثبت قصد االله حسب الاختيار ليس من الأعمال بل من الذي يدعو","قيل لها: »إن الكبير يستعبد للصغير«.","كما هو مكتوب: »أحببت يعقوب وأبغضت عيسو«.","فماذا نقول؟ ألعل عند االله ظلما؟ حاشا!","لأنه يقول لموسى: »إني أرحم من أرحم وأتراءف على من أتراءف«.","فإذا ليس لمن يشاء ولا لمن يسعى بل لله الذي يرحم.","لأنه يقول الكتاب لفرعون: »إني لهذا بعينه أقمتك لكي أظهر فيك قوتي ولكي ينادى باسمي في كل الأرض«.","فإذا هو يرحم من يشاء ويقسي من يشاء.","فستقول لي: »لماذا يلوم بعد لأن من يقاوم مشيئته؟«","بل من أنت أيها الإنسان الذي تجاوب االله؟ ألعل الجبلة تقول لجابلها: »لماذا صنعتني هكذا؟«","أم ليس للخزاف سلطان على الطين أن يصنع من كتلة واحدة إناء للكرامة وآخر للهوان؟","فماذا إن كان االله وهو يريد أن يظهر غضبه ويبين قوته احتمل بأناة كثيرة آنية غضب مهيأة للهلاك -","ولكي يبين غنى مجده على آنية رحمة قد سبق فأعدها للمجد","التي أيضا دعانا نحن إياها ليس من اليهود فقط بل من الأمم أيضا.","كما يقول في هوشع أيضا: »سأدعو الذي ليس شعبي شعبي والتي ليست محبوبة محبوبة.","ويكون في الموضع الذي قيل لهم فيه لستم شعبي أنه هناك يدعون أبناء االله الحي«.","وإشعياء يصرخ من جهة إسرائيل: »وإن كان عدد بني إسرائيل كرمل البحر فالبقية ستخلص.","لأنه متمم أمر وقاض بالبر. لأن الرب يصنع أمرا مقضيا به على الأرض«.","وكما سبق إشعياء فقال: »لولا أن رب الجنود أبقى لنا نسلا لصرنا مثل سدوم وشابهنا عمورة«.","فماذا نقول؟ إن الأمم الذين لم يسعوا في أثر البر أدركوا البر - البر الذي بالإيمان.","ولكن إسرائيل وهو يسعى في أثر ناموس البر لم يدرك ناموس البر!","لماذا؟ لأنه فعل ذلك ليس بالإيمان بل كأنه بأعمال الناموس. فإنهم اصطدموا بحجر الصدمة","كما هو مكتوب: »ها أنا أضع في صهيون حجر صدمة وصخرة عثرة وكل من يؤمن به لا يخزى«."],["أيها الإخوة إن مسرة قلبي وطلبتي إلى االله لأجل إسرائيل هي للخلاص.","لأني أشهد لهم أن لهم غيرة لله ولكن ليس حسب المعرفة.","لأنهم إذ كانوا يجهلون بر االله ويطلبون أن يثبتوا بر أنفسهم لم يخضعوا لبر االله.","لأن غاية الناموس هي: المسيح للبر لكل من يؤمن.","لأن موسى يكتب في البر الذي بالناموس: »إن الإنسان الذي يفعلها سيحيا بها«.","وأما البر الذي بالإيمان فيقول هكذا: »لا تقل في قلبك من يصعد إلى السماء؟« )أي ليحدر المسيح(","أو »من يهبط إلى الهاوية؟« )أي ليصعد المسيح من الأموات(","لكن ماذا يقول؟ »الكلمة قريبة منك في فمك وفي قلبك« )أي كلمة الإيمان التي نكرز بها(","لأنك إن اعترفت بفمك بالرب يسوع وآمنت بقلبك أن االله أقامه من الأموات خلصت.","لأن القلب يؤمن به للبر والفم يعترف به للخلاص.","لأن الكتاب يقول: »كل من يؤمن به لا يخزى«.","لأنه لا فرق بين اليهودي واليوناني لأن ربا واحدا للجميع غنيا لجميع الذين يدعون به.","لأن كل من يدعو باسم الرب يخلص.","فكيف يدعون بمن لم يؤمنوا به. وكيف يؤمنون بمن لم يسمعوا به؟ وكيف يسمعون بلا كارز؟","وكيف يكرزون إن لم يرسلوا؟ كما هو مكتوب: »ما أجمل أقدام المبشرين بالسلام المبشرين بالخيرات«.","لكن ليس الجميع قد أطاعوا الإنجيل لأن إشعياء يقول: »يا رب من صدق خبرنا؟«","إذا الإيمان بالخبر والخبر بكلمة االله.","لكنني أقول: ألعلهم لم يسمعوا؟ بلى! »إلى جميع الأرض خرج صوتهم وإلى أقاصي المسكونة أقوالهم«.","لكني أقول: ألعل إسرائيل لم يعلم؟ أولا موسى يقول: »أنا أغيركم بما ليس أمة. بأمة غبية أغيظكم«.","ثم إشعياء يتجاسر ويقول: »وجدت من الذين لم يطلبوني وصرت ظاهرا للذين لم يسألوا عني«.","أما من جهة إسرائيل فيقول: »طول النهار بسطت يدي إلى شعب معاند ومقاوم«."],["فأقول: ألعل االله رفض شعبه؟ حاشا! لأني أنا أيضا إسرائيلي من نسل إبراهيم من سبط بنيامين.","لم يرفض االله شعبه الذي سبق فعرفه. أم لستم تعلمون ماذا يقول الكتاب في إيليا؟ كيف يتوسل إلى االله ضد إسرائيل قائلا:","»يا رب قتلوا أنبياءك وهدموا مذابحك وبقيت أنا وحدي وهم يطلبون نفسي«.","لكن ماذا يقول له الوحي؟ »أبقيت لنفسي سبعة آلاف رجل لم يحنوا ركبة لبعل«.","فكذلك في الزمان الحاضر أيضا قد حصلت بقية حسب اختيار النعمة.","فإن كان بالنعمة فليس بعد بالأعمال وإلا فليست النعمة بعد نعمة. وإن كان بالأعمال فليس بعد نعمة وإلا فالعمل لا يكون بعد عملا.","فماذا؟ ما يطلبه إسرائيل ذلك لم ينله ولكن المختارون نالوه. وأما الباقون فتقسوا","كما هو مكتوب: »أعطاهم االله روح سبات وعيونا حتى لا يبصروا وآذانا حتى لا يسمعوا إلى هذا اليوم«.","وداود يقول: »لتصر مائدتهم فخا وقنصا وعثرة ومجازاة لهم.","لتظلم أعينهم كي لا يبصروا ولتحن ظهورهم في كل حين«.","فأقول: ألعلهم عثروا لكي يسقطوا؟ حاشا! بل بزلتهم صار الخلاص للأمم لإغارتهم.","فإن كانت زلتهم غنى للعالم ونقصانهم غنى للأمم فكم بالحري ملؤهم؟","فإني أقول لكم أيها الأمم: بما أني أنا رسول للأمم أمجد خدمتي","لعلي أغير أنسبائي وأخلص أناسا منهم.","لأنه إن كان رفضهم هو مصالحة العالم فماذا يكون اقتبالهم إلا حياة من الأموات؟","وإن كانت الباكورة مقدسة فكذلك العجين! وإن كان الأصل مقدسا فكذلك الأغصان!","فإن كان قد قطع بعض الأغصان وأنت زيتونة برية طعمت فيها فصرت شريكا في أصل الزيتونة ودسمها","فلا تفتخر على الأغصان. وإن افتخرت فأنت لست تحمل الأصل بل الأصل إياك يحمل!","فستقول: »قطعت الأغصان لأطعم أنا«.","حسنا! من أجل عدم الإيمان قطعت وأنت بالإيمان ثبت. لا تستكبر بل خف!","لأنه إن كان االله لم يشفق على الأغصان الطبيعية فلعله لا يشفق عليك أيضا!","فهوذا لطف االله وصرامته: أما الصرامة فعلى الذين سقطوا وأما اللطف فلك إن ثبت في اللطف وإلا فأنت أيضا ستقطع.","وهم إن لم يثبتوا في عدم الإيمان سيطعمون. لأن االله قادر أن يطعمهم أيضا.","لأنه إن كنت أنت قد قطعت من الزيتونة البرية حسب الطبيعة وطعمت بخلاف الطبيعة في زيتونة جيدة فكم بالحري يطعم هؤلاء الذين هم حسب الطبيعة في زيتونتهم الخاصة؟","فإني لست أريد أيها الإخوة أن تجهلوا هذا السر لئلا تكونوا عند أنفسكم حكماء. أن القساوة قد حصلت جزئيا لإسرائيل إلى أن يدخل ملؤ الأمم","وهكذا سيخلص جميع إسرائيل. كما هو مكتوب: »سيخرج من صهيون المنقذ ويرد الفجور عن يعقوب.","وهذا هو العهد من قبلي لهم متى نزعت خطاياهم«.","من جهة الإنجيل هم أعداء من أجلكم وأما من جهة الاختيار فهم أحباء من أجل الآباء","لأن هبات االله ودعوته هي بلا ندامة.","فإنه كما كنتم أنتم مرة لا تطيعون االله ولكن الآن رحمتم بعصيان هؤلاء","هكذا هؤلاء أيضا الآن لم يطيعوا لكي يرحموا هم أيضا برحمتكم.","لأن االله أغلق على الجميع معا في العصيان لكي يرحم الجميع.","يا لعمق غنى االله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن الاستقصاء!","»لأن من عرف فكر الرب أو من صار له مشيرا؟","أو من سبق فأعطاه فيكافأ؟«.","لأن منه وبه وله كل الأشياء. له المجد إلى الأبد. آمين."],["فأطلب إليكم أيها الإخوة برأفة االله أن تقدموا أجسادكم ذبيحة حية مقدسة مرضية عند االله عبادتكم العقلية.","ولا تشاكلوا هذا الدهر بل تغيروا عن شكلكم بتجديد أذهانكم لتختبروا ما هي إرادة االله الصالحة المرضية الكاملة.","فإني أقول بالنعمة المعطاة لي لكل من هو بينكم: أن لا يرتئي فوق ما ينبغي أن يرتئي بل يرتئي إلى التعقل كما قسم االله لكل واحد مقدارا من الإيمان.","فإنه كما في جسد واحد لنا أعضاء كثيرة ولكن ليس جميع الأعضاء لها عمل واحد","هكذا نحن الكثيرين: جسد واحد في المسيح وأعضاء بعضا لبعض كل واحد للآخر.","ولكن لنا مواهب مختلفة بحسب النعمة المعطاة لنا: أنبوة فبالنسبة إلى الإيمان","أم خدمة ففي الخدمة أم المعلم ففي التعليم","أم الواعظ ففي الوعظ المعطي فبسخاء المدبر فباجتهاد الراحم فبسرور.","المحبة فلتكن بلا رياء. كونوا كارهين الشر ملتصقين بالخير","وادين بعضكم بعضا بالمحبة الأخوية مقدمين بعضكم بعضا في الكرامة","غير متكاسلين في الاجتهاد حارين في الروح عابدين الرب","فرحين في الرجاء صابرين في الضيق مواظبين على الصلاة","مشتركين في احتياجات القديسين عاكفين على إضافة الغرباء.","باركوا على الذين يضطهدونكم. باركوا ولا تلعنوا.","فرحا مع الفرحين وبكاء مع الباكين.","مهتمين بعضكم لبعض اهتماما واحدا غير مهتمين بالأمور العالية بل منقادين إلى المتضعين. لا تكونوا حكماء عند أنفسكم.","لا تجازوا أحدا عن شر بشر. معتنين بأمور حسنة قدام جميع الناس.","إن كان ممكنا فحسب طاقتكم سالموا جميع الناس.","لا تنتقموا لأنفسكم أيها الأحباء بل أعطوا مكانا للغضب لأنه مكتوب: »لي النقمة أنا أجازي يقول الرب.","فإن جاع عدوك فأطعمه. وإن عطش فاسقه. لأنك إن فعلت هذا تجمع جمر نار على رأسه«.","لا يغلبنك الشر بل اغلب الشر بالخير."],["لتخضع كل نفس للسلاطين الفائقة لأنه ليس سلطان إلا من االله والسلاطين الكائنة هي مرتبة من االله","حتى إن من يقاوم السلطان يقاوم ترتيب االله والمقاومون سيأخذون لأنفسهم دينونة.","فإن الحكام ليسوا خوفا للأعمال الصالحة بل للشريرة. أفتريد أن لا تخاف السلطان؟ افعل الصلاح فيكون لك مدح منه","لأنه خادم االله للصلاح! ولكن إن فعلت الشر فخف لأنه لا يحمل السيف عبثا إذ هو خادم االله منتقم للغضب من الذي يفعل الشر.","لذلك يلزم أن يخضع له ليس بسبب الغضب فقط بل أيضا بسبب الضمير.","فإنكم لأجل هذا توفون الجزية أيضا إذ هم خدام االله مواظبون على ذلك بعينه.","فأعطوا الجميع حقوقهم: الجزية لمن له الجزية. الجباية لمن له الجباية. والخوف لمن له الخوف. والإكرام لمن له الإكرام.","لا تكونوا مديونين لأحد بشيء إلا بأن يحب بعضكم بعضا لأن من أحب غيره فقد أكمل الناموس.","لأن »لا تزن لا تقتل لا تسرق لا تشهد بالزور لا تشته« وإن كانت وصية أخرى هي مجموعة في هذه الكلمة: »أن تحب قريبك كنفسك«.","المحبة لا تصنع شرا للقريب فالمحبة هي تكميل الناموس.","هذا وإنكم عارفون الوقت أنها الآن ساعة لنستيقظ من النوم فإن خلاصنا الآن أقرب مما كان حين آمنا.","قد تناهى الليل وتقارب النهار فلنخلع أعمال الظلمة ونلبس أسلحة النور.","لنسلك بلياقة كما في النهار لا بالبطر والسكر لا بالمضاجع والعهر لا بالخصام والحسد.","بل البسوا الرب يسوع المسيح ولا تصنعوا تدبيرا للجسد لأجل الشهوات."],["ومن هو ضعيف في الإيمان فاقبلوه لا لمحاكمة الأفكار.","واحد يؤمن أن يأكل كل شيء وأما الضعيف فيأكل بقولا.","لا يزدر من يأكل بمن لا يأكل ولا يدن من لا يأكل من يأكل - لأن االله قبله.","من أنت الذي تدين عبد غيرك؟ هو لمولاه يثبت أو يسقط. ولكنه سيثبت لأن االله قادر أن يثبته.","واحد يعتبر يوما دون يوم وآخر يعتبر كل يوم - فليتيقن كل واحد في عقله:","الذي يهتم باليوم فللرب يهتم والذي لا يهتم باليوم فللرب لا يهتم. والذي يأكل فللرب يأكل لأنه يشكر االله والذي لا يأكل فللرب لا يأكل ويشكر االله.","لأن ليس أحد منا يعيش لذاته ولا أحد يموت لذاته.","لأننا إن عشنا فللرب نعيش وإن متنا فللرب نموت. فإن عشنا وإن متنا فللرب نحن.","لأنه لهذا مات المسيح وقام وعاش لكي يسود على الأحياء والأموات.","وأما أنت فلماذا تدين أخاك؟ أو أنت أيضا لماذا تزدري بأخيك؟ لأننا جميعا سوف نقف أمام كرسي المسيح","لأنه مكتوب: »أنا حي يقول الرب إنه لي ستجثو كل ركبة وكل لسان سيحمد االله«.","فإذا كل واحد منا سيعطي عن نفسه حسابا لله.","فلا نحاكم أيضا بعضنا بعضا بل بالحري احكموا بهذا: أن لا يوضع للأخ مصدمة أو معثرة.","إني عالم ومتيقن في الرب يسوع أن ليس شيء نجسا بذاته إلا من يحسب شيئا نجسا فله هو نجس.","فإن كان أخوك بسبب طعامك يحزن فلست تسلك بعد حسب المحبة. لا تهلك بطعامك ذلك الذي مات المسيح لأجله.","فلا يفتر على صلاحكم","لأن ليس ملكوت االله أكلا وشربا بل هو بر وسلام وفرح في الروح القدس.","لأن من خدم المسيح في هذه فهو مرضي عند االله ومزكى عند الناس.","فلنعكف إذا على ما هو للسلام وما هو للبنيان بعضنا لبعض.","لا تنقض لأجل الطعام عمل االله. كل الأشياء طاهرة لكنه شر للإنسان الذي يأكل بعثرة.","حسن أن لا تأكل لحما ولا تشرب خمرا ولا شيئا يصطدم به أخوك أو يعثر أو يضعف.","ألك إيمان؟ فليكن لك بنفسك أمام االله! طوبى لمن لا يدين نفسه في ما يستحسنه.","وأما الذي يرتاب فإن أكل يدان لأن ذلك ليس من الإيمان وكل ما ليس من الإيمان فهو خطية."],["فيجب علينا نحن الأقوياء أن نحتمل أضعاف الضعفاء ولا نرضي أنفسنا.","فليرض كل واحد منا قريبه للخير لأجل البنيان.","لأن المسيح أيضا لم يرض نفسه بل كما هو مكتوب: »تعييرات معيريك وقعت علي«.","لأن كل ما سبق فكتب كتب لأجل تعليمنا حتى بالصبر والتعزية بما في الكتب يكون لنا رجاء.","وليعطكم إله الصبر والتعزية أن تهتموا اهتماما واحدا فيما بينكم بحسب المسيح يسوع","لكي تمجدوا االله أبا ربنا يسوع المسيح بنفس واحدة وفم واحد.","لذلك اقبلوا بعضكم بعضا كما أن المسيح أيضا قبلنا لمجد االله.","وأقول: إن يسوع المسيح قد صار خادم الختان من أجل صدق االله حتى يثبت مواعيد الآباء.","وأما الأمم فمجدوا االله من أجل الرحمة كما هو مكتوب: »من أجل ذلك سأحمدك في الأمم وأرتل لاسمك«","ويقول أيضا: »تهللوا أيها الأمم مع شعبه«","وأيضا: »سبحوا الرب يا جميع الأمم وامدحوه يا جميع الشعوب«","وأيضا يقول إشعياء: »سيكون أصل يسى والقائم ليسود على الأمم. عليه سيكون رجاء الأمم«.","وليملأكم إله الرجاء كل سرور وسلام في الإيمان لتزدادوا في الرجاء بقوة الروح القدس.","وأنا نفسي أيضا متيقن من جهتكم يا إخوتي أنكم أنتم مشحونون صلاحا ومملوؤون كل علم قادرون أن ينذر بعضكم بعضا.","ولكن بأكثر جسارة كتبت إليكم جزئيا أيها الإخوة كمذكر لكم بسبب النعمة التي وهبت لي من االله","حتى أكون خادما ليسوع المسيح لأجل الأمم مباشرا لإنجيل االله ككاهن ليكون قربان الأمم مقبولا مقدسا بالروح القدس.","فلي افتخار في المسيح يسوع من جهة ما لله.","لأني لا أجسر أن أتكلم عن شيء مما لم يفعله المسيح بواسطتي لأجل إطاعة الأمم بالقول والفعل","بقوة آيات وعجائب بقوة روح االله. حتى إني من أورشليم وما حولها إلى إلليريكون قد أكملت التبشير بإنجيل المسيح.","ولكن كنت محترصا أن أبشر هكذا: ليس حيث سمي المسيح لئلا أبني على أساس لآخر.","بل كما هو مكتوب: »الذين لم يخبروا به سيبصرون والذين لم يسمعوا سيفهمون«.","لذلك كنت أعاق المرار الكثيرة عن المجيء إليكم.","وأما الآن فإذ ليس لي مكان بعد في هذه الأقاليم ولي اشتياق إلى المجيء إليكم منذ سنين كثيرة","فعندما أذهب إلى اسبانيا آتي إليكم. لأني أرجو أن أراكم في مروري وتشيعوني إلى هناك إن تملأت أولا منكم جزئيا.","ولكن الآن أنا ذاهب إلى أورشليم لأخدم القديسين","لأن أهل مكدونية وأخائية استحسنوا أن يصنعوا توزيعا لفقراء القديسين الذين في أورشليم.","استحسنوا ذلك وإنهم لهم مديونون! لأنه إن كان الأمم قد اشتركوا في روحياتهم يجب عليهم أن يخدموهم في الجسديات أيضا.","فمتى أكملت ذلك وختمت لهم هذا الثمر فسأمضي مارا بكم إلى اسبانيا.","وأنا أعلم أني إذا جئت إليكم سأجيء في ملء بركة إنجيل المسيح.","فأطلب إليكم أيها الإخوة بربنا يسوع المسيح وبمحبة الروح أن تجاهدوا معي في الصلوات من أجلي إلى االله","لكي أنقذ من الذين هم غير مؤمنين في اليهودية ولكي تكون خدمتي لأجل أورشليم مقبولة عند القديسين","حتى أجيء إليكم بفرح بإرادة االله وأستريح معكم.","إله السلام معكم أجمعين. آمين."],["أوصي إليكم بأختنا فيبي التي هي خادمة الكنيسة التي في كنخريا","كي تقبلوها في الرب كما يحق للقديسين وتقوموا لها في أي شيء احتاجته منكم لأنها صارت مساعدة لكثيرين ولي أنا أيضا.","سلموا على بريسكلا وأكيلا العاملين معي في المسيح يسوع","اللذين وضعا عنقيهما من أجل حياتي اللذين لست أنا وحدي أشكرهما بل أيضا جميع كنائس الأمم","وعلى الكنيسة التي في بيتهما. سلموا على أبينتوس حبيبي الذي هو باكورة أخائية للمسيح.","سلموا على مريم التي تعبت لأجلنا كثيرا.","سلموا على أندرونكوس ويونياس نسيبي المأسورين معي اللذين هما مشهوران بين الرسل وقد كانا في المسيح قبلي.","سلموا على أمبلياس حبيبي في الرب.","سلموا على أوربانوس العامل معنا في المسيح وعلى إستاخيس حبيبي.","سلموا على أبلس المزكى في المسيح. سلموا على الذين هم من أهل أرستوبولوس.","سلموا على هيروديون نسيبي. سلموا على الذين هم من أهل نركسوس الكائنين في الرب.","سلموا على تريفينا وتريفوسا التاعبتين في الرب. سلموا على برسيس المحبوبة التي تعبت كثيرا في الرب.","سلموا على روفس المختار في الرب وعلى أمه أمي.","سلموا على أسينكريتس وفليغون وهرماس وبتروباس وهرميس وعلى الإخوة الذين معهم.","سلموا على فيلولوغس وجوليا ونيريوس وأخته وأولمباس وعلى جميع القديسين الذين معهم.","سلموا بعضكم على بعض بقبلة مقدسة. كنائس المسيح تسلم عليكم.","وأطلب إليكم أيها الإخوة أن تلاحظوا الذين يصنعون الشقاقات والعثرات خلافا للتعليم الذي تعلمتموه وأعرضوا عنهم.","لأن مثل هؤلاء لا يخدمون ربنا يسوع المسيح بل بطونهم وبالكلام الطيب والأقوال الحسنة يخدعون قلوب السلماء.","لأن طاعتكم ذاعت إلى الجميع فأفرح أنا بكم وأريد أن تكونوا حكماء للخير وبسطاء للشر.","وإله السلام سيسحق الشيطان تحت أرجلكم سريعا. نعمة ربنا يسوع المسيح معكم. آمين.","يسلم عليكم تيموثاوس العامل معي ولوكيوس وياسون وسوسيباترس أنسبائي.","أنا ترتيوس كاتب هذه الرسالة أسلم عليكم في الرب.","يسلم عليكم غايس مضيفي ومضيف الكنيسة كلها. يسلم عليكم أراستس خازن المدينة وكوارتس الأخ.","نعمة ربنا يسوع المسيح مع جميعكم. آمين.","وللقادر أن يثبتكم حسب إنجيلي والكرازة بيسوع المسيح حسب إعلان السر الذي كان مكتوما في الأزمنة الأزلية","ولكن ظهر الآن وأعلم به جميع الأمم بالكتب النبوية حسب أمر الإله الأزلي لإطاعة الإيمان","الله الحكيم وحده بيسوع المسيح له المجد إلى الأبد. آمين. )كتبت إلى أهل رومية من كورنثوس على يد فيبي خادمة كنيسة كنخريا( رسالة بولس الرسول الأولى إلى أهل كورنثوس"]];
BBD["كورنثوس الأولى"]=[["بولس المدعو رسولا ليسوع المسيح بمشيئة االله وسوستانيس الأخ","إلى كنيسة االله التي في كورنثوس المقدسين في المسيح يسوع المدعوين قديسين مع جميع الذين يدعون باسم ربنا يسوع المسيح في كل مكان لهم ولنا.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","أشكر إلهي في كل حين من جهتكم على نعمة االله المعطاة لكم في يسوع المسيح","أنكم في كل شيء استغنيتم فيه في كل كلمة وكل علم","كما ثبتت فيكم شهادة المسيح","حتى إنكم لستم ناقصين في موهبة ما وأنتم متوقعون استعلان ربنا يسوع المسيح","الذي سيثبتكم أيضا إلى النهاية بلا لوم في يوم ربنا يسوع المسيح.","أمين هو االله الذي به دعيتم إلى شركة ابنه يسوع المسيح ربنا.","ولكنني أطلب إليكم أيها الإخوة باسم ربنا يسوع المسيح أن تقولوا جميعكم قولا واحدا ولا يكون بينكم انشقاقات بل كونوا كاملين في فكر واحد ورأي واحد","لأني أخبرت عنكم يا إخوتي من أهل خلوي أن بينكم خصومات.","فأنا أعني هذا: أن كل واحد منكم يقول: »أنا لبولس وأنا لأبلوس وأنا لصفا وأنا للمسيح«.","هل انقسم المسيح؟ ألعل بولس صلب لأجلكم أم باسم بولس اعتمدتم؟","أشكر االله أني لم أعمد أحدا منكم إلا كريسبس وغايس","حتى لا يقول أحد إني عمدت باسمي.","وعمدت أيضا بيت استفانوس. عدا ذلك لست أعلم هل عمدت أحدا آخر","لأن المسيح لم يرسلني لأعمد بل لأبشر - لا بحكمة كلام لئلا يتعطل صليب المسيح.","فإن كلمة الصليب عند الهالكين جهالة وأما عندنا نحن المخلصين فهي قوة االله","لأنه مكتوب: »سأبيد حكمة الحكماء وأرفض فهم الفهماء«.","أين الحكيم؟ أين الكاتب؟ أين مباحث هذا الدهر؟ ألم يجهل االله حكمة هذا العالم؟","لأنه إذ كان العالم في حكمة االله لم يعرف االله بالحكمة استحسن االله أن يخلص المؤمنين بجهالة الكرازة","لأن اليهود يسألون آية واليونانيين يطلبون حكمة","ولكننا نحن نكرز بالمسيح مصلوبا: لليهود عثرة ولليونانيين جهالة!","وأما للمدعوين: يهودا ويونانيين فبالمسيح قوة االله وحكمة االله.","لأن جهالة االله أحكم من الناس! وضعف االله أقوى من الناس!","فانظروا دعوتكم أيها الإخوة أن ليس كثيرون حكماء حسب الجسد. ليس كثيرون أقوياء. ليس كثيرون شرفاء.","بل اختار االله جهال العالم ليخزي الحكماء واختار االله ضعفاء العالم ليخزي الأقوياء","واختار االله أدنياء العالم والمزدرى وغير الموجود ليبطل الموجود","لكي لا يفتخر كل ذي جسد أمامه.","ومنه أنتم بالمسيح يسوع الذي صار لنا حكمة من االله وبرا وقداسة وفداء.","حتى كما هو مكتوب: »من افتخر فليفتخر بالرب«."],["وأنا لما أتيت إليكم أيها الإخوة أتيت ليس بسمو الكلام أو الحكمة مناديا لكم بشهادة االله","لأني لم أعزم أن أعرف شيئا بينكم إلا يسوع المسيح وإياه مصلوبا.","وأنا كنت عندكم في ضعف وخوف ورعدة كثيرة.","وكلامي وكرازتي لم يكونا بكلام الحكمة الإنسانية المقنع بل ببرهان الروح والقوة","لكي لا يكون إيمانكم بحكمة الناس بل بقوة االله.","لكننا نتكلم بحكمة بين الكاملين ولكن بحكمة ليست من هذا الدهر ولا من عظماء هذا الدهر الذين يبطلون.","بل نتكلم بحكمة االله في سر: الحكمة المكتومة التي سبق االله فعينها قبل الدهور لمجدنا","التي لم يعلمها أحد من عظماء هذا الدهر - لأن لو عرفوا لما صلبوا رب المجد.","بل كما هو مكتوب: »ما لم تر عين ولم تسمع أذن ولم يخطر على بال إنسان: ما أعده االله للذين يحبونه«.","فأعلنه االله لنا نحن بروحه. لأن الروح يفحص كل شيء حتى أعماق االله.","لأن من من الناس يعرف أمور الإنسان إلا روح الإنسان الذي فيه؟ هكذا أيضا أمور االله لا يعرفها أحد إلا روح االله.","ونحن لم نأخذ روح العالم بل الروح الذي من االله لنعرف الأشياء الموهوبة لنا من االله","التي نتكلم بها أيضا لا بأقوال تعلمها حكمة إنسانية بل بما يعلمه الروح القدس قارنين الروحيات بالروحيات.","ولكن الإنسان الطبيعي لا يقبل ما لروح االله لأنه عنده جهالة ولا يقدر أن يعرفه لأنه إنما يحكم فيه روحيا.","وأما الروحي فيحكم في كل شيء وهو لا يحكم فيه من أحد.","لأنه من عرف فكر الرب فيعلمه؟ وأما نحن فلنا فكر المسيح."],["وأنا أيها الإخوة لم أستطع أن أكلمكم كروحيين بل كجسديين كأطفال في المسيح","سقيتكم لبنا لا طعاما لأنكم لم تكونوا بعد تستطيعون بل الآن أيضا لا تستطيعون","لأنكم بعد جسديون. فإنه إذ فيكم حسد وخصام وانشقاق ألستم جسديين وتسلكون بحسب البشر؟","لأنه متى قال واحد: »أنا لبولس« وآخر: »أنا لأبلوس« أفلستم جسديين؟","فمن هو بولس ومن هو أبلوس؟ بل خادمان آمنتم بواسطتهما وكما أعطى الرب لكل واحد:","أنا غرست وأبلوس سقى لكن االله كان ينمي.","إذا ليس الغارس شيئا ولا الساقي بل االله الذي ينمي.","والغارس والساقي هما واحد ولكن كل واحد سيأخذ أجرته بحسب تعبه.","فإننا نحن عاملان مع االله وأنتم فلاحة االله بناء االله.","حسب نعمة االله المعطاة لي كبناء حكيم قد وضعت أساسا وآخر يبني عليه. ولكن فلينظر كل واحد كيف يبني عليه.","فإنه لا يستطيع أحد أن يضع أساسا آخر غير الذي وضع الذي هو يسوع المسيح.","ولكن إن كان أحد يبني على هذا الأساس ذهبا فضة حجارة كريمة خشبا عشبا قشا","فعمل كل واحد سيصير ظاهرا لأن اليوم سيبينه. لأنه بنار يستعلن وستمتحن النار عمل كل واحد ما هو.","إن بقي عمل أحد قد بناه عليه فسيأخذ أجرة.","إن احترق عمل أحد فسيخسر وأما هو فسيخلص ولكن كما بنار.","أما تعلمون أنكم هيكل االله وروح االله يسكن فيكم؟","إن كان أحد يفسد هيكل االله فسيفسده االله لأن هيكل االله مقدس الذي أنتم هو.","لا يخدعن أحد نفسه. إن كان أحد يظن أنه حكيم بينكم في هذا الدهر فليصر جاهلا لكي يصير حكيما!","لأن حكمة هذا العالم هي جهالة عند االله لأنه مكتوب: »الآخذ الحكماء بمكرهم«.","وأيضا: »الرب يعلم أفكار الحكماء أنها باطلة«.","إذا لا يفتخرن أحد بالناس فإن كل شيء لكم:","أبولس أم أبلوس أم صفا أم العالم أم الحياة أم الموت أم الأشياء الحاضرة أم المستقبلة. كل شيء لكم.","وأما أنتم فللمسيح والمسيح لله."],["هكذا فليحسبنا الإنسان كخدام المسيح ووكلاء سرائر االله","ثم يسأل في الوكلاء لكي يوجد الإنسان أمينا.","وأما أنا فأقل شيء عندي أن يحكم في منكم أو من يوم بشر. بل لست أحكم في نفسي أيضا.","فإني لست أشعر بشيء في ذاتي. لكنني لست بذلك مبررا. ولكن الذي يحكم في هو الرب.","إذا لا تحكموا في شيء قبل الوقت حتى يأتي الرب الذي سينير خفايا الظلام ويظهر آراء القلوب. وحينئذ يكون المدح لكل واحد من االله.","فهذا أيها الإخوة حولته تشبيها إلى نفسي وإلى أبلوس من أجلكم لكي تتعلموا فينا أن لا تفتكروا فوق ما هو مكتوب كي لا ينتفخ أحد لأجل الواحد على الآخر.","لأنه من يميزك؟ وأي شيء لك لم تأخذه؟ وإن كنت قد أخذت فلماذا تفتخر كأنك لم تأخذ؟","إنكم قد شبعتم! قد استغنيتم! ملكتم بدوننا! وليتكم ملكتم لنملك نحن أيضا معكم!","فإني أرى أن االله أبرزنا نحن الرسل آخرين كأننا محكوم علينا بالموت. لأننا صرنا منظرا للعالم للملائكة والناس.","نحن جهال من أجل المسيح وأما أنتم فحكماء في المسيح! نحن ضعفاء وأما أنتم فأقوياء! أنتم مكرمون وأما نحن فبلا كرامة!","إلى هذه الساعة نجوع ونعطش ونعرى ونلكم وليس لنا إقامة","ونتعب عاملين بأيدينا. نشتم فنبارك. نضطهد فنحتمل.","يفترى علينا فنعظ. صرنا كأقذار العالم ووسخ كل شيء إلى الآن.","ليس لكي أخجلكم أكتب بهذا بل كأولادي الأحباء أنذركم.","لأنه وإن كان لكم ربوات من المرشدين في المسيح لكن ليس آباء كثيرون. لأني أنا ولدتكم في المسيح يسوع بالإنجيل.","فأطلب إليكم أن تكونوا متمثلين بي.","لذلك أرسلت إليكم تيموثاوس الذي هو ابني الحبيب والأمين في الرب الذي يذكركم بطرقي في المسيح كما أعلم في كل مكان في كل كنيسة.","فانتفخ قوم كأني لست آتيا إليكم.","ولكني سآتي إليكم سريعا إن شاء الرب فسأعرف ليس كلام الذين انتفخوا بل قوتهم.","لأن ملكوت االله ليس بكلام بل بقوة.","ماذا تريدون؟ أبعصا آتي إليكم أم بالمحبة وروح الوداعة؟"],["يسمع مطلقا أن بينكم زنى! وزنى هكذا لا يسمى بين الأمم حتى أن تكون للإنسان امرأة أبيه.","أفأنتم منتفخون وبالحري لم تنوحوا حتى يرفع من وسطكم الذي فعل هذا الفعل؟","فإني أنا كأني غائب بالجسد ولكن حاضر بالروح قد حكمت كأني حاضر في الذي فعل هذا هكذا","باسم ربنا يسوع المسيح - إذ أنتم وروحي مجتمعون مع قوة ربنا يسوع المسيح -","أن يسلم مثل هذا للشيطان لهلاك الجسد لكي تخلص الروح في يوم الرب يسوع.","ليس افتخاركم حسنا. ألستم تعلمون أن خميرة صغيرة تخمر العجين كله؟","إذا نقوا منكم الخميرة العتيقة لكي تكونوا عجينا جديدا كما أنتم فطير. لأن فصحنا أيضا المسيح قد ذبح لأجلنا.","إذا لنعيد ليس بخميرة عتيقة ولا بخميرة الشر والخبث بل بفطير الإخلاص والحق.","كتبت إليكم في الرسالة أن لا تخالطوا الزناة.","وليس مطلقا زناة هذا العالم أو الطماعين أو الخاطفين أو عبدة الأوثان وإلا فيلزمكم أن تخرجوا من العالم.","وأما الآن فكتبت إليكم: إن كان أحد مدعو أخا زانيا أو طماعا أو عابد وثن أو شتاما أو سكيرا أو خاطفا أن لا تخالطوا ولا تؤاكلوا مثل هذا.","لأنه ماذا لي أن أدين الذين من خارج ألستم أنتم تدينون الذين من داخل.","أما الذين من خارج فالله يدينهم. فاعزلوا الخبيث من بينكم."],["أيتجاسر منكم أحد له دعوى على آخر أن يحاكم عند الظالمين وليس عند القديسين؟","ألستم تعلمون أن القديسين سيدينون العالم؟ فإن كان العالم يدان بكم أفأنتم غير مستأهلين للمحاكم الصغرى؟","ألستم تعلمون أننا سندين ملائكة؟ فبالأولى أمور هذه الحياة!","فإن كان لكم محاكم في أمور هذه الحياة فأجلسوا المحتقرين في الكنيسة قضاة!","لتخجيلكم أقول. أهكذا ليس بينكم حكيم ولا واحد يقدر أن يقضي بين إخوته؟","لكن الأخ يحاكم الأخ وذلك عند غير المؤمنين.","فالآن فيكم عيب مطلقا لأن عندكم محاكمات بعضكم مع بعض. لماذا لا تظلمون بالحري؟ لماذا لا تسلبون بالحري؟","لكن أنتم تظلمون وتسلبون وذلك للإخوة.","أم لستم تعلمون أن الظالمين لا يرثون ملكوت االله؟ لا تضلوا! لا زناة ولا عبدة أوثان ولا فاسقون ولا مأبونون ولا مضاجعو ذكور","ولا سارقون ولا طماعون ولا سكيرون ولا شتامون ولا خاطفون يرثون ملكوت االله.","وهكذا كان أناس منكم. لكن اغتسلتم بل تقدستم بل تبررتم باسم الرب يسوع وبروح إلهنا.","كل الأشياء تحل لي لكن ليس كل الأشياء توافق. كل الأشياء تحل لي لكن لا يتسلط علي شيء.","الأطعمة للجوف والجوف للأطعمة واالله سيبيد هذا وتلك. ولكن الجسد ليس للزنا بل للرب والرب للجسد.","والله قد أقام الرب وسيقيمنا نحن أيضا بقوته.","ألستم تعلمون أن أجسادكم هي أعضاء المسيح؟ أفآخذ أعضاء المسيح وأجعلها أعضاء زانية؟ حاشا!","أم لستم تعلمون أن من التصق بزانية هو جسد واحد لأنه يقول: »يكون الاثنان جسدا واحدا«.","وأما من التصق بالرب فهو روح واحد.","اهربوا من الزنا. كل خطية يفعلها الإنسان هي خارجة عن الجسد لكن الذي يزني يخطئ إلى جسده.","أم لستم تعلمون أن جسدكم هو هيكل للروح القدس الذي فيكم الذي لكم من االله وأنكم لستم لأنفسكم؟","لأنكم قد اشتريتم بثمن. فمجدوا االله في أجسادكم وفي أرواحكم التي هي لله."],["وأما من جهة الأمور التي كتبتم لي عنها فحسن للرجل أن لا يمس امرأة.","ولكن لسبب الزنا ليكن لكل واحد امرأته وليكن لكل واحدة رجلها.","ليوف الرجل المرأة حقها الواجب وكذلك المرأة أيضا الرجل.","ليس للمرأة تسلط على جسدها بل للرجل وكذلك الرجل أيضا ليس له تسلط على جسده بل للمرأة.","لا يسلب أحدكم الآخر إلا أن يكون على موافقة إلى حين لكي تتفرغوا للصوم والصلاة ثم تجتمعوا أيضا معا لكي لا يجربكم الشيطان لسبب عدم نزاهتكم.","ولكن أقول هذا على سبيل الإذن لا على سبيل الأمر.","لأني أريد أن يكون جميع الناس كما أنا. لكن كل واحد له موهبته الخاصة من االله. الواحد هكذا والآخر هكذا.","ولكن أقول لغير المتزوجين وللأرامل إنه حسن لهم إذا لبثوا كما أنا.","ولكن إن لم يضبطوا أنفسهم فليتزوجوا لأن التزوج أصلح من التحرق.","وأما المتزوجون فأوصيهم لا أنا بل الرب أن لا تفارق المرأة رجلها.","وإن فارقته فلتلبث غير متزوجة أو لتصالح رجلها. ولا يترك الرجل امرأته.","وأما الباقون فأقول لهم أنا لا الرب: إن كان أخ له امرأة غير مؤمنة وهي ترتضي أن تسكن معه فلا يتركها.","والمرأة التي لها رجل غير مؤمن وهو يرتضي أن يسكن معها فلا تتركه.","لأن الرجل غير المؤمن مقدس في المرأة والمرأة غير المؤمنة مقدسة في الرجل - وإلا فأولادكم نجسون. وأما الآن فهم مقدسون.","ولكن إن فارق غير المؤمن فليفارق. ليس الأخ أو الأخت مستعبدا في مثل هذه الأحوال. ولكن االله قد دعانا في السلام.","لأنه كيف تعلمين أيتها المرأة هل تخلصين الرجل؟ أو كيف تعلم أيها الرجل هل تخلص المرأة؟","غير أنه كما قسم االله لكل واحد كما دعا الرب كل واحد هكذا ليسلك. وهكذا أنا آمر في جميع الكنائس.","دعي أحد وهو مختون فلا يصر أغلف. دعي أحد في الغرلة فلا يختتن.","ليس الختان شيئا وليست الغرلة شيئا بل حفظ وصايا االله.","الدعوة التي دعي فيها كل واحد فليلبث فيها.","دعيت وأنت عبد فلا يهمك. بل وإن استطعت أن تصير حرا فاستعملها بالحري.","لأن من دعي في الرب وهو عبد فهو عتيق الرب. كذلك أيضا الحر المدعو هو عبد للمسيح.","قد اشتريتم بثمن فلا تصيروا عبيدا للناس.","ما دعي كل واحد فيه أيها الإخوة فليلبث في ذلك مع االله.","وأما العذارى فليس عندي أمر من الرب فيهن ولكنني أعطي رأيا كمن رحمه الرب أن يكون أمينا.","فأظن أن هذا حسن لسبب الضيق الحاضر. أنه حسن للإنسان أن يكون هكذا:","أنت مرتبط بامرأة فلا تطلب الانفصال. أنت منفصل عن امرأة فلا تطلب امرأة.","لكنك وإن تزوجت لم تخطئ. وإن تزوجت العذراء لم تخطئ. ولكن مثل هؤلاء يكون لهم ضيق في الجسد. وأما أنا فإني أشفق عليكم.","فأقول هذا أيها الإخوة: الوقت منذ الآن مقصر لكي يكون الذين لهم نساء كأن ليس لهم","والذين يبكون كأنهم لا يبكون والذين يفرحون كأنهم لا يفرحون والذين يشترون كأنهم لا يملكون","والذين يستعملون هذا العالم كأنهم لا يستعملونه. لأن هيئة هذا العالم تزول.","فأريد أن تكونوا بلا هم. غير المتزوج يهتم في ما للرب كيف يرضي الرب","وأما المتزوج فيهتم في ما للعالم كيف يرضي امرأته.","إن بين الزوجة والعذراء فرقا: غير المتزوجة تهتم في ما للرب لتكون مقدسة جسدا وروحا. وأما المتزوجة فتهتم في ما للعالم كيف ترضي رجلها.","هذا أقوله لخيركم ليس لكي ألقي عليكم وهقا بل لأجل اللياقة والمثابرة للرب من دون ارتباك.","ولكن إن كان أحد يظن أنه يعمل بدون لياقة نحو عذرائه إذا تجاوزت الوقت وهكذا لزم أن يصير فليفعل ما يريد. إنه لا يخطئ. فليتزوجا.","وأما من أقام راسخا في قلبه وليس له اضطرار بل له سلطان على إرادته وقد عزم على هذا في قلبه أن يحفظ عذراءه فحسنا يفعل.","إذا من زوج فحسنا يفعل ومن لا يزوج يفعل أحسن.","المرأة مرتبطة بالناموس ما دام رجلها حيا. ولكن إن مات رجلها فهي حرة لكي تتزوج بمن تريد في الرب فقط.","ولكنها أكثر غبطة إن لبثت هكذا بحسب رأيي. وأظن أني أنا أيضا عندي روح االله."],["وأما من جهة ما ذبح للأوثان فنعلم أن لجميعنا علما. العلم ينفخ ولكن المحبة تبني.","فإن كان أحد يظن أنه يعرف شيئا فإنه لم يعرف شيئا بعد كما يجب أن يعرف!","ولكن إن كان أحد يحب االله فهذا معروف عنده.","فمن جهة أكل ما ذبح للأوثان نعلم أن ليس وثن في العالم وأن ليس إله آخر إلا واحدا.","لأنه وإن وجد ما يسمى آلهة سواء كان في السماء أو على الأرض كما يوجد آلهة كثيرون وأرباب كثيرون.","لكن لنا إله واحد: الآب الذي منه جميع الأشياء ونحن له. ورب واحد: يسوع المسيح الذي به جميع الأشياء ونحن به.","ولكن ليس العلم في الجميع. بل أناس بالضمير نحو الوثن إلى الآن يأكلون كأنه مما ذبح لوثن. فضميرهم إذ هو ضعيف يتنجس.","ولكن الطعام لا يقدمنا إلى االله لأننا إن أكلنا لا نزيد وإن لم نأكل لا ننقص.","ولكن انظروا لئلا يصير سلطانكم هذا معثرة للضعفاء.","لأنه إن رآك أحد يا من له علم متكئا في هيكل وثن أفلا يتقوى ضميره إذ هو ضعيف حتى يأكل ما ذبح للأوثان؟","فيهلك بسبب علمك الأخ الضعيف الذي مات المسيح من أجله.","وهكذا إذ تخطئون إلى الإخوة وتجرحون ضميرهم الضعيف تخطئون إلى المسيح.","لذلك إن كان طعام يعثر أخي فلن آكل لحما إلى الأبد لئلا أعثر أخي."],["ألست أنا رسولا؟ ألست أنا حرا؟ أما رأيت يسوع المسيح ربنا؟ ألستم أنتم عملي في الرب؟!","إن كنت لست رسولا إلى آخرين فإنما أنا إليكم رسول لأنكم أنتم ختم رسالتي في الرب.","هذا هو احتجاجي عند الذين يفحصونني.","ألعلنا ليس لنا سلطان أن نأكل ونشرب؟","ألعلنا ليس لنا سلطان أن نجول بأخت زوجة كباقي الرسل وإخوة الرب وصفا؟","أم أنا وبرنابا وحدنا ليس لنا سلطان أن لا نشتغل؟","من تجند قط بنفقة نفسه؟ ومن يغرس كرما ومن ثمره لا يأكل؟ أو من يرعى رعية ومن لبن الرعية لا يأكل؟","ألعلي أتكلم بهذا كإنسان؟ أم ليس الناموس أيضا يقول هذا؟","فإنه مكتوب في ناموس موسى: »لا تكم ثورا دارسا«. ألعل االله تهمه الثيران؟","أم يقول مطلقا من أجلنا؟ إنه من أجلنا مكتوب. لأنه ينبغي للحراث أن يحرث على رجاء وللدارس على الرجاء أن يكون شريكا في رجائه.","إن كنا نحن قد زرعنا لكم الروحيات أفعظيم إن حصدنا منكم الجسديات؟","إن كان آخرون شركاء في السلطان عليكم أفلسنا نحن بالأولى؟ لكننا لم نستعمل هذا السلطان بل نتحمل كل شيء لئلا نجعل عائقا لإنجيل المسيح.","ألستم تعلمون أن الذين يعملون في الأشياء المقدسة من الهيكل يأكلون؟ الذين يلازمون المذبح يشاركون المذبح.","هكذا أيضا أمر الرب: أن الذين ينادون بالإنجيل من الإنجيل يعيشون.","أما أنا فلم أستعمل شيئا من هذا ولا كتبت هذا لكي يصير في هكذا. لأنه خير لي أن أموت من أن يعطل أحد فخري.","لأنه إن كنت أبشر فليس لي فخر إذ الضرورة موضوعة علي فويل لي إن كنت لا أبشر.","فإنه إن كنت أفعل هذا طوعا فلي أجر ولكن إن كان كرها فقد استؤمنت على وكالة.","فما هو أجري؟ إذ وأنا أبشر أجعل إنجيل المسيح بلا نفقة حتى لم أستعمل سلطاني في الإنجيل.","فإني إذ كنت حرا من الجميع استعبدت نفسي للجميع لأربح الأكثرين.","فصرت لليهود كيهودي لأربح اليهود وللذين تحت الناموس كأني تحت الناموس لأربح الذين تحت الناموس","وللذين بلا ناموس كأني بلا ناموس - مع أني لست بلا ناموس لله بل تحت ناموس للمسيح - لأربح الذين بلا ناموس.","صرت للضعفاء كضعيف لأربح الضعفاء. صرت للكل كل شيء لأخلص على كل حال قوما.","وهذا أنا أفعله لأجل الإنجيل لأكون شريكا فيه.","ألستم تعلمون أن الذين يركضون في الميدان جميعهم يركضون ولكن واحدا يأخذ الجعالة؟ هكذا اركضوا لكي تنالوا.","وكل من يجاهد يضبط نفسه في كل شيء. أما أولئك فلكي يأخذوا إكليلا يفنى وأما نحن فإكليلا لا يفنى.","إذا أنا أركض هكذا كأنه ليس عن غير يقين. هكذا أضارب كأني لا أضرب الهواء.","بل أقمع جسدي وأستعبده حتى بعد ما كرزت للآخرين لا أصير أنا نفسي مرفوضا."],["فإني لست أريد أيها الإخوة أن تجهلوا أن آباءنا جميعهم كانوا تحت السحابة وجميعهم اجتازوا في البحر","وجميعهم اعتمدوا لموسى في السحابة وفي البحر","وجميعهم أكلوا طعاما واحدا روحيا","وجميعهم شربوا شرابا واحدا روحيا - لأنهم كانوا يشربون من صخرة روحية تابعتهم والصخرة كانت المسيح.","لكن بأكثرهم لم يسر االله لأنهم طرحوا في القفر.","وهذه الأمور حدثت مثالا لنا حتى لا نكون نحن مشتهين شرورا كما اشتهى أولئك.","فلا تكونوا عبدة أوثان كما كان أناس منهم كما هو مكتوب: »جلس الشعب للأكل والشرب ثم قاموا للعب«.","ولا نزن كما زنى أناس منهم فسقط في يوم واحد ثلاثة وعشرون ألفا.","ولا نجرب المسيح كما جرب أيضا أناس منهم فأهلكتهم الحيات.","ولا تتذمروا كما تذمر أيضا أناس منهم فأهلكهم المهلك.","فهذه الأمور جميعها أصابتهم مثالا وكتبت لإنذارنا نحن الذين انتهت إلينا أواخر الدهور.","إذا من يظن أنه قائم فلينظر أن لا يسقط.","لم تصبكم تجربة إلا بشرية. ولكن االله أمين الذي لا يدعكم تجربون فوق ما تستطيعون بل سيجعل مع التجربة أيضا المنفذ لتستطيعوا أن تحتملوا.","لذلك يا أحبائي اهربوا من عبادة الأوثان.","أقول كما للحكماء: احكموا أنتم في ما أقول.","كأس البركة التي نباركها أليست هي شركة دم المسيح؟ الخبز الذي نكسره أليس هو شركة جسد المسيح؟","فإننا نحن الكثيرين خبز واحد جسد واحد لأننا جميعنا نشترك في الخبز الواحد.","انظروا إسرائيل حسب الجسد. أليس الذين يأكلون الذبائح هم شركاء المذبح؟","فماذا أقول؟ أإن الوثن شيء أو إن ما ذبح للوثن شيء؟","بل إن ما يذبحه الأمم فإنما يذبحونه للشياطين لا لله. فلست أريد أن تكونوا أنتم شركاء الشياطين.","لا تقدرون أن تشربوا كأس الرب وكأس شياطين. لا تقدرون أن تشتركوا في مائدة الرب وفي مائدة شياطين.","أم نغير الرب؟ ألعلنا أقوى منه؟","كل الأشياء تحل لي لكن ليس كل الأشياء توافق. كل الأشياء تحل لي ولكن ليس كل الأشياء تبني.","لا يطلب أحد ما هو لنفسه بل كل واحد ما هو للآخر.","كل ما يباع في الملحمة كلوه غير فاحصين عن شيء من أجل الضمير","لأن للرب الأرض وملأها.","وإن كان أحد من غير المؤمنين يدعوكم وتريدون أن تذهبوا فكل ما يقدم لكم كلوا منه غير فاحصين من أجل الضمير.","ولكن إن قال لكم أحد: »هذا مذبوح لوثن« فلا تأكلوا من أجل ذاك الذي أعلمكم والضمير. لأن للرب الأرض وملأها","أقول الضمير - ليس ضميرك أنت بل ضمير الآخر. لأنه لماذا يحكم في حريتي من ضمير آخر؟","فإن كنت أنا أتناول بشكر فلماذا يفترى علي لأجل ما أشكر عليه؟","فإذا كنتم تأكلون أو تشربون أو تفعلون شيئا فافعلوا كل شيء لمجد االله.","كونوا بلا عثرة لليهود ولليونانيين ولكنيسة االله.","كما أنا أيضا أرضي الجميع في كل شيء غير طالب ما يوافق نفسي بل الكثيرين لكي يخلصوا."],["كونوا متمثلين بي كما أنا أيضا بالمسيح.","فأمدحكم أيها الإخوة على أنكم تذكرونني في كل شيء وتحفظون التعاليم كما سلمتها إليكم.","ولكن أريد أن تعلموا أن رأس كل رجل هو المسيح. وأما رأس المرأة فهو الرجل. ورأس المسيح هو االله.","كل رجل يصلي أو يتنبأ وله على رأسه شيء يشين رأسه.","وأما كل امرأة تصلي أو تتنبأ ورأسها غير مغطى فتشين رأسها لأنها والمحلوقة شيء واحد بعينه.","إذ المرأة إن كانت لا تتغطى فليقص شعرها. وإن كان قبيحا بالمرأة أن تقص أو تحلق فلتتغط.","فإن الرجل لا ينبغي أن يغطي رأسه لكونه صورة االله ومجده. وأما المرأة فهي مجد الرجل.","لأن الرجل ليس من المرأة بل المرأة من الرجل.","ولأن الرجل لم يخلق من أجل المرأة بل المرأة من أجل الرجل.","لهذا ينبغي للمرأة أن يكون لها سلطان على رأسها من أجل الملائكة.","غير أن الرجل ليس من دون المرأة ولا المرأة من دون الرجل في الرب.","لأنه كما أن المرأة هي من الرجل هكذا الرجل أيضا هو بالمرأة. ولكن جميع الأشياء هي من االله.","احكموا في أنفسكم: هل يليق بالمرأة أن تصلي إلى االله وهي غير مغطاة؟","أم ليست الطبيعة نفسها تعلمكم أن الرجل إن كان يرخي شعره فهو عيب له؟","وأما المرأة إن كانت ترخي شعرها فهو مجد لها لأن الشعر قد أعطي لها عوض برقع.","ولكن إن كان أحد يظهر أنه يحب الخصام فليس لنا نحن عادة مثل هذه ولا لكنائس االله.","ولكنني إذ أوصي بهذا لست أمدح كونكم تجتمعون ليس للأفضل بل للأردإ.","لأني أولا حين تجتمعون في الكنيسة أسمع أن بينكم انشقاقات وأصدق بعض التصديق.","لأنه لا بد أن يكون بينكم بدع أيضا ليكون المزكون ظاهرين بينكم.","فحين تجتمعون معا ليس هو لأكل عشاء الرب.","لأن كل واحد يسبق فيأخذ عشاء نفسه في الأكل فالواحد يجوع والآخر يسكر.","أفليس لكم بيوت لتأكلوا فيها وتشربوا؟ أم تستهينون بكنيسة االله وتخجلون الذين ليس لهم؟ ماذا أقول لكم! أأمدحكم على هذا؟ لست أمدحكم!","لأنني تسلمت من الرب ما سلمتكم أيضا: إن الرب يسوع في الليلة التي أسلم فيها أخذ خبزا","وشكر فكسر وقال: »خذوا كلوا هذا هو جسدي المكسور لأجلكم. اصنعوا هذا لذكري«.","كذلك الكأس أيضا بعدما تعشوا قائلا: »هذه الكأس هي العهد الجديد بدمي. اصنعوا هذا كلما شربتم لذكري«.","فإنكم كلما أكلتم هذا الخبز وشربتم هذه الكأس تخبرون بموت الرب إلى أن يجيء.","إذا أي من أكل هذا الخبز أو شرب كأس الرب بدون استحقاق يكون مجرما في جسد الرب ودمه.","ولكن ليمتحن الإنسان نفسه وهكذا يأكل من الخبز ويشرب من الكأس.","لأن الذي يأكل ويشرب بدون استحقاق يأكل ويشرب دينونة لنفسه غير مميز جسد الرب.","من أجل هذا فيكم كثيرون ضعفاء ومرضى وكثيرون يرقدون.","لأننا لو كنا حكمنا على أنفسنا لما حكم علينا","ولكن إذ قد حكم علينا نؤدب من الرب لكي لا ندان مع العالم.","إذا يا إخوتي حين تجتمعون للأكل انتظروا بعضكم بعضا.","إن كان أحد يجوع فليأكل في البيت كي لا تجتمعوا للدينونة. وأما الأمور الباقية فعندما أجيء أرتبها."],["وأما من جهة المواهب الروحية أيها الإخوة فلست أريد أن تجهلوا.","أنتم تعلمون أنكم كنتم أمما منقادين إلى الأوثان البكم كما كنتم تساقون.","لذلك أعرفكم أن ليس أحد وهو يتكلم بروح االله يقول: »يسوع أناثيما«. وليس أحد يقدر أن يقول: »يسوع رب« إلا بالروح القدس.","فأنواع مواهب موجودة ولكن الروح واحد.","وأنواع خدم موجودة ولكن الرب واحد.","وأنواع أعمال موجودة ولكن االله واحد الذي يعمل الكل في الكل.","ولكنه لكل واحد يعطى إظهار الروح للمنفعة.","فإنه لواحد يعطى بالروح كلام حكمة. ولآخر كلام علم بحسب الروح الواحد.","ولآخر إيمان بالروح الواحد. ولآخر مواهب شفاء بالروح الواحد.","ولآخر عمل قوات ولآخر نبوة ولآخر تمييز الأرواح ولآخر أنواع ألسنة ولآخر ترجمة ألسنة.","ولكن هذه كلها يعملها الروح الواحد بعينه قاسما لكل واحد بمفرده كما يشاء.","لأنه كما أن الجسد هو واحد وله أعضاء كثيرة وكل أعضاء الجسد الواحد إذا كانت كثيرة هي جسد واحد كذلك المسيح أيضا.","لأننا جميعنا بروح واحد أيضا اعتمدنا إلى جسد واحد يهودا كنا أم يونانيين عبيدا أم أحرارا. وجميعنا سقينا روحا واحدا.","فإن الجسد أيضا ليس عضوا واحدا بل أعضاء كثيرة.","إن قالت الرجل: »لأني لست يدا لست من الجسد«. أفلم تكن لذلك من الجسد؟","وإن قالت الأذن: »لأني لست عينا لست من الجسد«. أفلم تكن لذلك من الجسد؟","لو كان كل الجسد عينا فأين السمع؟ لو كان الكل سمعا فأين الشم؟","وأما الآن فقد وضع االله الأعضاء كل واحد منها في الجسد كما أراد.","ولكن لو كان جميعها عضوا واحدا أين الجسد؟","فالآن أعضاء كثيرة ولكن جسد واحد.","لا تقدر العين أن تقول لليد: »لا حاجة لي إليك«. أو الرأس أيضا للرجلين: »لا حاجة لي إليكما«.","بل بالأولى أعضاء الجسد التي تظهر أضعف هي ضرورية.","وأعضاء الجسد التي نحسب أنها بلا كرامة نعطيها كرامة أفضل. والأعضاء القبيحة فينا لها جمال أفضل.","وأما الجميلة فينا فليس لها احتياج. لكن االله مزج الجسد معطيا الناقص كرامة أفضل","لكي لا يكون انشقاق في الجسد بل تهتم الأعضاء اهتماما واحدا بعضها لبعض.","فإن كان عضو واحد يتألم فجميع الأعضاء تتألم معه. وإن كان عضو واحد يكرم فجميع الأعضاء تفرح معه.","وأما أنتم فجسد المسيح وأعضاؤه أفرادا.","فوضع االله أناسا في الكنيسة: أولا رسلا ثانيا أنبياء ثالثا معلمين ثم قوات وبعد ذلك مواهب شفاء أعوانا تدابير وأنواع ألسنة.","ألعل الجميع رسل؟ ألعل الجميع أنبياء؟ ألعل الجميع معلمون؟ ألعل الجميع أصحاب قوات؟","ألعل للجميع مواهب شفاء؟ ألعل الجميع يتكلمون بألسنة؟ ألعل الجميع يترجمون؟","ولكن جدوا للمواهب الحسنى. وأيضا أريكم طريقا أفضل:"],["إن كنت أتكلم بألسنة الناس والملائكة ولكن ليس لي محبة فقد صرت نحاسا يطن أو صنجا يرن.","وإن كانت لي نبوة وأعلم جميع الأسرار وكل علم وإن كان لي كل الإيمان حتى أنقل الجبال ولكن ليس لي محبة فلست شيئا.","وإن أطعمت كل أموالي وإن سلمت جسدي حتى أحترق ولكن ليس لي محبة فلا أنتفع شيئا.","المحبة تتأنى وترفق. المحبة لا تحسد. المحبة لا تتفاخر ولا تنتفخ","ولا تقبح ولا تطلب ما لنفسها ولا تحتد ولا تظن السؤ","ولا تفرح بالإثم بل تفرح بالحق.","وتحتمل كل شيء وتصدق كل شيء وترجو كل شيء وتصبر على كل شيء.","المحبة لا تسقط أبدا. وأما النبوات فستبطل والألسنة فستنتهي والعلم فسيبطل.","لأننا نعلم بعض العلم ونتنبأ بعض التنبؤ.","ولكن متى جاء الكامل فحينئذ يبطل ما هو بعض.","لما كنت طفلا كطفل كنت أتكلم وكطفل كنت أفطن وكطفل كنت أفتكر. ولكن لما صرت رجلا أبطلت ما للطفل.","فإننا ننظر الآن في مرآة في لغز لكن حينئذ وجها لوجه. الآن أعرف بعض المعرفة لكن حينئذ سأعرف كما عرفت.","أما الآن فيثبت الإيمان والرجاء والمحبة هذه الثلاثة ولكن أعظمهن المحبة."],["اتبعوا المحبة ولكن جدوا للمواهب الروحية وبالأولى أن تتنبأوا.","لأن من يتكلم بلسان لا يكلم الناس بل االله لأن ليس أحد يسمع. ولكنه بالروح يتكلم بأسرار.","وأما من يتنبأ فيكلم الناس ببنيان ووعظ وتسلية.","من يتكلم بلسان يبني نفسه وأما من يتنبأ فيبني الكنيسة.","إني أريد أن جميعكم تتكلمون بألسنة ولكن بالأولى أن تتنبأوا. لأن من يتنبأ أعظم ممن يتكلم بألسنة إلا إذا ترجم حتى تنال الكنيسة بنيانا.","فالآن أيها الإخوة إن جئت إليكم متكلما بألسنة فماذا أنفعكم إن لم أكلمكم إما بإعلان أو بعلم أو بنبوة أو بتعليم؟","الأشياء العادمة النفوس التي تعطي صوتا: مزمار أو قيثارة مع ذلك إن لم تعط فرقا للنغمات فكيف يعرف ما زمر أو ما عزف به؟","فإنه إن أعطى البوق أيضا صوتا غير واضح فمن يتهيأ للقتال؟","هكذا أنتم أيضا إن لم تعطوا باللسان كلاما يفهم فكيف يعرف ما تكلم به؟ فإنكم تكونون تتكلمون في الهواء!","ربما تكون أنواع لغات هذا عددها في العالم وليس شيء منها بلا معنى.","فإن كنت لا أعرف قوة اللغة أكون عند المتكلم أعجميا والمتكلم أعجميا عندي.","هكذا أنتم أيضا إذ إنكم غيورون للمواهب الروحية اطلبوا لأجل بنيان الكنيسة أن تزدادوا.","لذلك من يتكلم بلسان فليصل لكي يترجم.","لأنه إن كنت أصلي بلسان فروحي تصلي وأما ذهني فهو بلا ثمر.","فما هو إذا؟ أصلي بالروح وأصلي بالذهن أيضا. أرتل بالروح وأرتل بالذهن أيضا.","وإلا فإن باركت بالروح فالذي يشغل مكان العامي كيف يقول »آمين« عند شكرك؟ لأنه لا يعرف ماذا تقول!","فإنك أنت تشكر حسنا! ولكن الآخر لا يبنى.","أشكر إلهي أني أتكلم بألسنة أكثر من جميعكم.","ولكن في كنيسة أريد أن أتكلم خمس كلمات بذهني لكي أعلم آخرين أيضا أكثر من عشرة آلاف كلمة بلسان.","أيها الإخوة لا تكونوا أولادا في أذهانكم بل كونوا أولادا في الشر وأما في الأذهان فكونوا كاملين.","مكتوب في الناموس: »إني بذوي ألسنة أخرى وبشفاه أخرى سأكلم هذا الشعب ولا هكذا يسمعون لي يقول الرب«.","إذا الألسنة آية لا للمؤمنين بل لغير المؤمنين. أما النبوة فليست لغير المؤمنين بل للمؤمنين.","فإن اجتمعت الكنيسة كلها في مكان واحد وكان الجميع يتكلمون بألسنة فدخل عاميون أو غير مؤمنين أفلا يقولون إنكم تهذون؟","ولكن إن كان الجميع يتنبأون فدخل أحد غير مؤمن أو عامي فإنه يوبخ من الجميع. يحكم عليه من الجميع.","وهكذا تصير خفايا قلبه ظاهرة. وهكذا يخر على وجهه ويسجد لله مناديا أن االله بالحقيقة فيكم.","فما هو إذا أيها الإخوة؟ متى اجتمعتم فكل واحد منكم له مزمور له تعليم له لسان له إعلان له ترجمة: فليكن كل شيء للبنيان.","إن كان أحد يتكلم بلسان فاثنين اثنين أو على الأكثر ثلاثة ثلاثة وبترتيب وليترجم واحد.","ولكن إن لم يكن مترجم فليصمت في الكنيسة وليكلم نفسه واالله.","أما الأنبياء فليتكلم اثنان أو ثلاثة وليحكم الآخرون.","ولكن إن أعلن لآخر جالس فليسكت الأول.","لأنكم تقدرون جميعكم أن تتنبأوا واحدا واحدا ليتعلم الجميع ويتعزى الجميع.","وأرواح الأنبياء خاضعة للأنبياء.","لأن االله ليس إله تشويش بل إله سلام كما في جميع كنائس القديسين.","لتصمت نساؤكم في الكنائس لأنه ليس مأذونا لهن أن يتكلمن بل يخضعن كما يقول الناموس أيضا.","ولكن إن كن يردن أن يتعلمن شيئا فليسألن رجالهن في البيت لأنه قبيح بالنساء أن تتكلم في كنيسة.","أم منكم خرجت كلمة االله؟ أم إليكم وحدكم انتهت؟","إن كان أحد يحسب نفسه نبيا أو روحيا فليعلم ما أكتبه إليكم أنه وصايا الرب.","ولكن إن يجهل أحد فليجهل!","إذا أيها الإخوة جدوا للتنبؤ ولا تمنعوا التكلم بألسنة.","وليكن كل شيء بلياقة وبحسب ترتيب."],["وأعرفكم أيها الإخوة بالإنجيل الذي بشرتكم به وقبلتموه وتقومون فيه","وبه أيضا تخلصون إن كنتم تذكرون أي كلام بشرتكم به. إلا إذا كنتم قد آمنتم عبثا!","فإنني سلمت إليكم في الأول ما قبلته أنا أيضا: أن المسيح مات من أجل خطايانا حسب الكتب","وأنه دفن وأنه قام في اليوم الثالث حسب الكتب","وأنه ظهر لصفا ثم للاثني عشر.","وبعد ذلك ظهر دفعة واحدة لأكثر من خمسمئة أخ أكثرهم باق إلى الآن. ولكن بعضهم قد رقدوا.","وبعد ذلك ظهر ليعقوب ثم للرسل أجمعين.","وآخر الكل كأنه للسقط ظهر لي أنا.","لأني أصغر الرسل أنا الذي لست أهلا لأن أدعى رسولا لأني اضطهدت كنيسة االله.","ولكن بنعمة االله أنا ما أنا ونعمته المعطاة لي لم تكن باطلة بل أنا تعبت أكثر منهم جميعهم. ولكن لا أنا بل نعمة االله التي معي.","فسواء أنا أم أولئك هكذا نكرز وهكذا آمنتم.","ولكن إن كان المسيح يكرز به أنه قام من الأموات فكيف يقول قوم بينكم إن ليس قيامة أموات؟","فإن لم تكن قيامة أموات فلا يكون المسيح قد قام!","وإن لم يكن المسيح قد قام فباطلة كرازتنا وباطل أيضا إيمانكم","ونوجد نحن أيضا شهود زور لله لأننا شهدنا من جهة االله أنه أقام المسيح وهو لم يقمه - إن كان الموتى لا يقومون.","لأنه إن كان الموتى لا يقومون فلا يكون المسيح قد قام.","وإن لم يكن المسيح قد قام فباطل إيمانكم. أنتم بعد في خطاياكم!","إذا الذين رقدوا في المسيح أيضا هلكوا!","إن كان لنا في هذه الحياة فقط رجاء في المسيح فإننا أشقى جميع الناس.","ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين.","فإنه إذ الموت بإنسان بإنسان أيضا قيامة الأموات.","لأنه كما في آدم يموت الجميع هكذا في المسيح سيحيا الجميع.","ولكن كل واحد في رتبته. المسيح باكورة ثم الذين للمسيح في مجيئه.","وبعد ذلك النهاية متى سلم الملك لله الآب متى أبطل كل رياسة وكل سلطان وكل قوة.","لأنه يجب أن يملك حتى يضع جميع الأعداء تحت قدميه.","آخر عدو يبطل هو الموت.","لأنه أخضع كل شيء تحت قدميه. ولكن حينما يقول »إن كل شيء قد أخضع« فواضح أنه غير الذي أخضع له الكل.","ومتى أخضع له الكل فحينئذ الابن نفسه أيضا سيخضع للذي أخضع له الكل كي يكون االله الكل في الكل.","وإلا فماذا يصنع الذين يعتمدون من أجل الأموات؟ إن كان الأموات لا يقومون البتة فلماذا يعتمدون من أجل الأموات؟","ولماذا نخاطر نحن كل ساعة؟","إني بافتخاركم الذي لي في يسوع المسيح ربنا أموت كل يوم.","إن كنت كإنسان قد حاربت وحوشا في أفسس فما المنفعة لي؟ إن كان الأموات لا يقومون فلنأكل ونشرب لأننا غدا نموت!","لا تضلوا! فإن المعاشرات الردية تفسد الأخلاق الجيدة.","اصحوا للبر ولا تخطئوا لأن قوما ليست لهم معرفة بالله. أقول ذلك لتخجيلكم!","لكن يقول قائل: »كيف يقام الأموات وبأي جسم يأتون؟«","يا غبي! الذي تزرعه لا يحيا إن لم يمت.","والذي تزرعه لست تزرع الجسم الذي سوف يصير بل حبة مجردة ربما من حنطة أو أحد البواقي.","ولكن االله يعطيها جسما كما أراد. ولكل واحد من البزور جسمه.","ليس كل جسد جسدا واحدا بل للناس جسد واحد وللبهائم جسد آخر وللسمك آخر وللطير آخر.","وأجسام سماوية وأجسام أرضية. لكن مجد السماويات شيء ومجد الأرضيات آخر.","مجد الشمس شيء ومجد القمر آخر ومجد النجوم آخر. لأن نجما يمتاز عن نجم في المجد.","هكذا أيضا قيامة الأموات: يزرع في فساد ويقام في عدم فساد.","يزرع في هوان ويقام في مجد. يزرع في ضعف ويقام في قوة.","يزرع جسما حيوانيا ويقام جسما روحانيا. يوجد جسم حيواني ويوجد جسم روحاني.","هكذا مكتوب أيضا: »صار آدم الإنسان الأول نفسا حية وآدم الأخير روحا محييا«.","لكن ليس الروحاني أولا بل الحيواني وبعد ذلك الروحاني.","الإنسان الأول من الأرض ترابي. الإنسان الثاني الرب من السماء.","كما هو الترابي هكذا الترابيون أيضا وكما هو السماوي هكذا السماويون أيضا.","وكما لبسنا صورة الترابي سنلبس أيضا صورة السماوي.","فأقول هذا أيها الإخوة: إن لحما ودما لا يقدران أن يرثا ملكوت االله ولا يرث الفساد عدم الفساد.","هوذا سر أقوله لكم: لا نرقد كلنا ولكننا كلنا نتغير","في لحظة في طرفة عين عند البوق الأخير. فإنه سيبوق فيقام الأموات عديمي فساد ونحن نتغير.","لأن هذا الفاسد لا بد أن يلبس عدم فساد وهذا المائت يلبس عدم موت.","ومتى لبس هذا الفاسد عدم فساد ولبس هذا المائت عدم موت فحينئذ تصير الكلمة المكتوبة: »ابتلع الموت إلى غلبة«.","أين شوكتك يا موت؟ أين غلبتك يا هاوية؟","أما شوكة الموت فهي الخطية وقوة الخطية هي الناموس.","ولكن شكرا لله الذي يعطينا الغلبة بربنا يسوع المسيح.","إذا يا إخوتي الأحباء كونوا راسخين غير متزعزعين مكثرين في عمل الرب كل حين عالمين أن تعبكم ليس باطلا في الرب."],["وأما من جهة الجمع لأجل القديسين فكما أوصيت كنائس غلاطية هكذا افعلوا أنتم أيضا.","في كل أول أسبوع ليضع كل واحد منكم عنده خازنا ما تيسر حتى إذا جئت لا يكون جمع حينئذ.","ومتى حضرت فالذين تستحسنونهم أرسلهم برسائل ليحملوا إحسانكم إلى أورشليم.","وإن كان يستحق أن أذهب أنا أيضا فسيذهبون معي.","وسأجيء إليكم متى اجتزت بمكدونية لأني أجتاز بمكدونية.","وربما أمكث عندكم أو أشتي أيضا لكي تشيعوني إلى حيثما أذهب.","لأني لست أريد الآن أن أراكم في العبور لأني أرجو أن أمكث عندكم زمانا إن أذن الرب.","ولكنني أمكث في أفسس إلى يوم الخمسين","لأنه قد انفتح لي باب عظيم فعال ويوجد معاندون كثيرون.","ثم إن أتى تيموثاوس فانظروا أن يكون عندكم بلا خوف. لأنه يعمل عمل الرب كما أنا أيضا.","فلا يحتقره أحد بل شيعوه بسلام ليأتي إلي لأني أنتظره مع الإخوة.","وأما من جهة أبلوس الأخ فطلبت إليه كثيرا أن يأتي إليكم مع الإخوة ولم تكن له إرادة البتة أن يأتي الآن. ولكنه سيأتي متى توفق الوقت.","اسهروا. اثبتوا في الإيمان. كونوا رجالا. تقووا.","لتصر كل أموركم في محبة.","وأطلب إليكم أيها الإخوة: أنتم تعرفون بيت استفاناس أنهم باكورة أخائية وقد رتبوا أنفسهم لخدمة القديسين","كي تخضعوا أنتم أيضا لمثل هؤلاء وكل من يعمل معهم ويتعب.","ثم إني أفرح بمجيء استفاناس وفرتوناتوس وأخائيكوس لأن نقصانكم هؤلاء قد جبروه","إذ أراحوا روحي وروحكم. فاعرفوا مثل هؤلاء.","تسلم عليكم كنائس أسيا. يسلم عليكم في الرب كثيرا أكيلا وبريسكلا مع الكنيسة التي في بيتهما.","يسلم عليكم الإخوة أجمعون. سلموا بعضكم على بعض بقبلة مقدسة.","السلام بيدي أنا بولس.","إن كان أحد لا يحب الرب يسوع المسيح فليكن أناثيما. ماران أثا.","نعمة الرب يسوع المسيح معكم.","محبتي مع جميعكم في المسيح يسوع. آمين رسالة بولس الرسول الثانية إلى أهل كورنثوس"]];
BBD["كورنثوس الثانية"]=[["بولس، رسول يسوع المسيح بمشيئة االله، وتيموثاوس الأخ، إلى كنيسة االله التي في كورنثوس، مع القديسين أجمعين الذين في جميع أخائية.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","مبارك االله أبو ربنا يسوع المسيح، أبو الرأفة وإله كل تعزية،","الذي يعزينا في كل ضيقتنا، حتى نستطيع أن نعزي الذين هم في كل ضيقة بالتعزية التي نتعزى نحن بها من االله.","لأنه كما تكثر آلام المسيح فينا، كذلك بالمسيح تكثر تعزيتنا أيضا.","فإن كنا نتضايق فلأجل تعزيتكم وخلاصكم، العامل في احتمال نفس الآلام التي نتألم بها نحن أيضا. أو نتعزى فلأجل تعزيتكم وخلاصكم.","فرجاؤنا من أجلكم ثابت. عالمين أنكم كما أنتم شركاء في الآلام، كذلك في التعزية أيضا.","فإننا لا نريد أن تجهلوا أيها الإخوة من جهة ضيقتنا التي أصابتنا في أسيا، أننا تثقلنا جدا فوق الطاقة، حتى أيسنا من الحياة أيضا.","لكن كان لنا في أنفسنا حكم الموت، لكي لا نكون متكلين على أنفسنا بل على االله الذي يقيم الأموات،","الذي نجانا من موت مثل هذا، وهو ينجي. الذي لنا رجاء فيه أنه سينجي أيضا فيما بعد.","وأنتم أيضا مساعدون بالصلاة لأجلنا، لكي يؤدى شكر لأجلنا من أشخاص كثيرين، على ما وهب لنا بواسطة كثيرين.","لأن فخرنا هو هذا: شهادة ضميرنا أننا في بساطة وإخلاص االله، لا في حكمة جسدية بل في نعمة االله، تصرفنا في العالم، ولا سيما من نحوكم.","فإننا لا نكتب إليكم بشيء آخر سوى ما تقرأون أو تعرفون. وأنا أرجو أنكم ستعرفون إلى النهاية أيضا،","كما عرفتمونا أيضا بعض المعرفة أننا فخركم، كما أنكم أيضا فخرنا في يوم الرب يسوع.","وبهذه الثقة كنت أشاء أن آتي إليكم أولا، لتكون لكم نعمة ثانية.","وأن أمر بكم إلى مكدونية، وآتي أيضا من مكدونية إليكم، وأشيع منكم إلى اليهودية.","فإذ أنا عازم على هذا، ألعلي استعملت الخفة، أم أعزم على ما أعزم بحسب الجسد، كي يكون عندي نعم نعم ولا لا؟","لكن أمين هو االله إن كلامنا لكم لم يكن نعم ولا.","لأن ابن االله يسوع المسيح، الذي كرز به بينكم بواسطتنا، أنا وسلوانس وتيموثاوس، لم يكن نعم ولا، بل قد كان فيه نعم.","لأن مهما كانت مواعيد االله فهو فيه النعم وفيه الآمين، لمجد االله، بواسطتنا.","ولكن الذي يثبتنا معكم في المسيح، وقد مسحنا، هو االله","الذي ختمنا أيضا، وأعطى عربون الروح في قلوبنا.","ولكني أستشهد االله على نفسي أني إشفاقا عليكم لم آت إلى كورنثوس.","ليس أننا نسلود على إيمانكم بل نحن موازرون لسروركم. لأنكم بالإيمان تثبتون."],["ولكني جزمت بهذا في نفسي أن لا آتي إليكم أيضا في حزن.","لأنه إن كنت أحزنكم أنا، فمن هو الذي يفرحني إلا الذي أحزنته؟","وكتبت لكم هذا عينه حتى إذا جئت لا يكون لي حزن من الذين كان يجب أن أفرح بهم، واثقا بجميعكم أن فرحي هو فرح جميعكم.","لأني من حزن كثير وكآبة قلب كتبت إليكم بدموع كثيرة، لا لكي تحزنوا، بل لكي تعرفوا المحبة التي عندي ولا سيما من نحوكم.","ولكن إن كان أحد قد أحزن، فإنه لم يحزني، بل أحزن جميعكم بعض الحزن لكي لا أثقل.","مثل هذا يكفيه هذا القصاص الذي من الأكثرين،","حتى تكونوا - بالعكس - تسامحونه بالحري وتعزونه، لئلا يبتلع مثل هذا من الحزن المفرط.","لذلك أطلب أن تمكنوا له المحبة.","لأني لهذا كتبت لكي أعرف تزكيتكم، هل أنتم طائعون في كل شيء؟","والذي تسامحونه بشيء فأنا أيضا. لأني أنا ما سامحت به - إن كنت قد سامحت بشيء - فمن أجلكم بحضرة المسيح،","لئلا يطمع فينا الشيطان، لأننا لا نجهل أفكاره.","ولكن لما جئت إلى ترواس، لأجل إنجيل المسيح وانفتح لي باب في الرب،","لم تكن لي راحة في روحي، لأني لم أجد تيطس أخي. لكن ودعتهم فخرجت إلى مكدونية.","ولكن شكرا لله الذي يقودنا في موكب نصرته في المسيح كل حين، ويظهر بنا رائحة معرفته في كل مكان.","لأننا رائحة المسيح الذكية لله، في الذين يخلصون وفي الذين يهلكون.","لهؤلاء رائحة موت لموت، ولأولئك رائحة حياة لحياة. ومن هو كفوء لهذه الأمور؟","لأننا لسنا كالكثيرين غاشين كلمة االله، لكن كما من إخلاص، بل كما من االله نتكلم أمام االله في المسيح."],["أفنبتدئ نمدح أنفسنا، أم لعلنا نحتاج كقوم رسائل توصية إليكم، أو رسائل توصية منكم؟","أنتم رسالتنا، مكتوبة في قلوبنا، معروفة ومقروءة من جميع الناس.","ظاهرين أنكم رسالة المسيح، مخدومة منا، مكتوبة لا بحبر بل بروح االله الحي، لا في ألواح حجرية بل في ألواح قلب لحمية.","ولكن لنا ثقة مثل هذه بالمسيح لدى االله.","ليس أننا كفاة من أنفسنا أن نفتكر شيئا كأنه من أنفسنا، بل كفايتنا من االله،","الذي جعلنا كفاة لأن نكون خدام عهد جديد. لا الحرف بل الروح. لأن الحرف يقتل ولكن الروح يحيي.","ثم إن كانت خدمة الموت، المنقوشة بأحرف في حجارة، قد حصلت في مجد، حتى لم يقدر بنو إسرائيل أن ينظروا إلى وجه موسى لسبب مجد وجهه الزائل،","فكيف لا تكون بالأولى خدمة الروح في مجد؟","لأنه إن كانت خدمة الدينونة مجدا، فبالأولى كثيرا تزيد خدمة البر في مجد.","فإن الممجد أيضا لم يمجد من هذا القبيل لسبب المجد الفائق.","لأنه إن كان الزائل في مجد، فبالأولى كثيرا يكون الدائم في مجد.","فإذ لنا رجاء مثل هذا نستعمل مجاهرة كثيرة.","وليس كما كان موسى يضع برقعا على وجهه لكي لا ينظر بنو إسرائيل إلى نهاية الزائل.","بل أغلظت أذهانهم، لأنه حتى اليوم ذلك البرقع نفسه عند قراءة العهد العتيق باق غير منكشف، الذي يبطل في المسيح.","لكن حتى اليوم، حين يقرأ موسى، البرقع موضوع على قلبهم.","ولكن عندما يرجع إلى الرب يرفع البرقع.","وأما الرب فهو الروح، وحيث روح الرب هناك حرية.","ونحن جميعا ناظرين مجد الرب بوجه مكشوف، كما في مرآة، نتغير إلى تلك الصورة عينها، من مجد إلى مجد، كما من الرب الروح."],["من أجل ذلك، إذ لنا هذه الخدمة كما رحمنا، لا نفشل.","بل قد رفضنا خفايا الخزي، غير سالكين في مكر، ولا غاشين كلمة االله، بل بإظهار الحق، مادحين أنفسنا لدى ضمير كل إنسان قدام االله.","ولكن إن كان إنجيلنا مكتوما، فإنما هو مكتوم في الهالكين،","الذين فيهم إله هذا الدهر قد أعمى أذهان غير المؤمنين، لئلا تضيء لهم إنارة إنجيل مجد المسيح، الذي هو صورة االله.","فإننا لسنا نكرز بأنفسنا، بل بالمسيح يسوع ربا، ولكن بأنفسنا عبيدا لكم من أجل يسوع.","لأن االله الذي قال أن يشرق نور من ظلمة، هو الذي أشرق في قلوبنا، لإنارة معرفة مجد االله في وجه يسوع المسيح.","ولكن لنا هذا الكنز في أوان خزفية، ليكون فضل القوة لله لا منا.","مكتئبين في كل شيء، لكن غير متضايقين. متحيرين، لكن غير يائسين.","مضطهدين، لكن غير متروكين. مطروحين، لكن غير هالكين.","حاملين في الجسد كل حين إماتة الرب يسوع، لكي تظهر حياة يسوع أيضا في جسدنا.","لأننا نحن الأحياء نسلم دائما للموت من أجل يسوع، لكي تظهر حياة يسوع أيضا في جسدنا المائت.","إذا الموت يعمل فينا، ولكن الحياة فيكم.","فإذ لنا روح الإيمان عينه، حسب المكتوب »آمنت لذلك تكلمت« - نحن أيضا نؤمن ولذلك نتكلم أيضا.","عالمين أن الذي أقام الرب يسوع سيقيمنا نحن أيضا بيسوع، ويحضرنا معكم.","لأن جميع الأشياء هي من أجلكم، لكي تكون النعمة وهي قد كثرت بالأكثرين، تزيد الشكر لمجد االله.","لذلك لا نفشل. بل وإن كان إنساننا الخارج يفنى، فالداخل يتجدد يوما فيوما.","لأن خفة ضيقتنا الوقتية تنشئ لنا أكثر فأكثر ثقل مجد أبديا.","ونحن غير ناظرين إلى الأشياء التي ترى، بل إلى التي لا ترى. لأن التي ترى وقتية، وأما التي لا ترى فأبدية."],["لأننا نعلم أنه إن نقض بيت خيمتنا الأرضي، فلنا في السماوات بناء من االله، بيت غير مصنوع بيد، أبدي.","فإننا في هذه أيضا نئن مشتاقين إلى أن نلبس فوقها مسكننا الذي من السماء.","وإن كنا لابسين لا نوجد عراة.","فإننا نحن الذين في الخيمة نئن مثقلين، إذ لسنا نريد أن نخلعها بل أن نلبس فوقها، لكي يبتلع المائت من الحياة.","ولكن الذي صنعنا لهذا عينه هو االله، الذي أعطانا أيضا عربون الروح.","فإذا نحن واثقون كل حين وعالمون أننا ونحن مستوطنون في الجسد فنحن متغربون عن الرب.","لأننا بالإيمان نسلك لا بالعيان.","فنثق ونسر بالأولى أن نتغرب عن الجسد ونستوطن عند الرب.","لذلك نحترص أيضا مستوطنين كنا أو متغربين أن نكون مرضيين عنده.","لأنه لا بد أننا جميعا نظهر أمام كرسي المسيح، لينال كل واحد ما كان بالجسد بحسب ما صنع، خيرا كان أم شرا.","فإذ نحن عالمون مخافة الرب نقنع الناس. وأما االله فقد صرنا ظاهرين له، وأرجو أننا قد صرنا ظاهرين في ضمائركم أيضا.","لأننا لسنا نمدح أنفسنا أيضا لديكم، بل نعطيكم فرصة للافتخار من جهتنا، ليكون لكم جواب على الذين يفتخرون بالوجه لا بالقلب.","لأننا إن صرنا مختلين فلله، أو كنا عاقلين فلكم.","لأن محبة المسيح تحصرنا. إذ نحن نحسب هذا: أنه إن كان واحد قد مات لأجل الجميع. فالجميع إذا ماتوا.","وهو مات لأجل الجميع كي يعيش الأحياء فيما بعد لا لأنفسهم، بل للذي مات لأجلهم وقام.","إذا نحن من الآن لا نعرف أحدا حسب الجسد. وإن كنا قد عرفنا المسيح حسب الجسد، لكن الآن لا نعرفه بعد.","إذا إن كان أحد في المسيح فهو خليقة جديدة. الأشياء العتيقة قد مضت. هوذا الكل قد صار جديدا.","ولكن الكل من االله، الذي صالحنا لنفسه بيسوع المسيح، وأعطانا خدمة المصالحة،","أي إن االله كان في المسيح مصالحا العالم لنفسه، غير حاسب لهم خطاياهم، وواضعا فينا كلمة المصالحة.","إذا نسعى كسفراء عن المسيح، كأن االله يعظ بنا. نطلب عن المسيح: تصالحوا مع االله.","لأنه جعل الذي لم يعرف خطية، خطية لأجلنا، لنصير نحن بر االله فيه."],["فإذ نحن عاملون معه نطلب أن لا تقبلوا نعمة االله باطلا.","لأنه يقول: »في وقت مقبول سمعتك، وفي يوم خلاص أعنتك«. هوذا الآن وقت مقبول. هوذا الآن يوم خلاص.","ولسنا نجعل عثرة في شيء لئلا تلام الخدمة.","بل في كل شيء نظهر أنفسنا كخدام االله، في صبر كثير، في شدائد، في ضرورات، في ضيقات،","في ضربات، في سجون، في اضطرابات، في أتعاب، في أسهار، في أصوام،","في طهارة، في علم، في أناة، في لطف، في الروح القدس، في محبة بلا رياء،","في كلام الحق، في قوة االله بسلاح البر لليمين ولليسار.","بمجد وهوان. بصيت رديء وصيت حسن. كمضلين ونحن صادقون.","كمجهولين ونحن معروفون. كمائتين وها نحن نحيا. كمؤدبين ونحن غير مقتولين.","كحزانى ونحن دائما فرحون. كفقراء ونحن نغني كثيرين. كأن لا شيء لنا ونحن نملك كل شيء.","فمنا مفتوح إليكم أيها الكورنثيون. قلبنا متسع.","لستم متضيقين فينا بل متضيقين في أحشائكم.","فجزاء لذلك أقول كما لأولادي: كونوا أنتم أيضا متسعين!","لا تكونوا تحت نير مع غير المؤمنين، لأنه أية خلطة للبر والإثم؟ وأية شركة للنور مع الظلمة؟","وأي اتفاق للمسيح مع بليعال؟ وأي نصيب للمؤمن مع غير المؤمن؟","وأية موافقة لهيكل االله مع الأوثان؟ فإنكم أنتم هيكل االله الحي، كما قال االله: »إني سأسكن فيهم وأسير بينهم، وأكون لهم إلها وهم يكونون لي شعبا.","لذلك اخرجوا من وسطهم واعتزلوا، يقول الرب. ولا تمسوا نجسا فأقبلكم،","وأكون لكم أبا وأنتم تكونون لي بنين وبنات« يقول الرب القادر على كل شيء."],["فإذ لنا هذه المواعيد أيها الأحباء لنطهر ذواتنا من كل دنس الجسد والروح، مكملين القداسة في خوف االله.","اقبلونا. لم نظلم أحدا. لم نفسد أحدا. لم نطمع في أحد.","لا أقول هذا لأجل دينونة، لأني قد قلت سابقا إنكم في قلوبنا لنموت معكم ونعيش معكم.","لي ثقة كثيرة بكم. لي افتخار كثير من جهتكم. قد امتلأت تعزية وازددت فرحا جدا في جميع ضيقاتنا.","لأننا لما أتينا إلى مكدونية لم يكن لجسدنا شيء من الراحة بل كنا مكتئبين في كل شيء. من خارج خصومات. من داخل مخاوف.","لكن االله الذي يعزي المتضعين عزانا بمجيء تيطس.","وليس بمجيئه فقط بل أيضا بالتعزية التي تعزى بها بسببكم وهو يخبرنا بشوقكم ونوحكم وغيرتكم لأجلي، حتى إني فرحت أكثر.","لأني وإن كنت قد أحزنتكم بالرسالة لست أندم، مع أني ندمت. فإني أرى أن تلك الرسالة أحزنتكم ولو إلى ساعة.","الآن أنا أفرح، لا لأنكم حزنتم، بل لأنكم حزنتم للتوبة. لأنكم حزنتم بحسب مشيئة االله لكي لا تتخسروا منا في شيء.","لأن الحزن الذي بحسب مشيئة االله ينشئ توبة لخلاص بلا ندامة، وأما حزن العالم فينشئ موتا.","فإنه هوذا حزنكم هذا عينه بحسب مشيئة االله، كم أنشأ فيكم من الاجتهاد، بل من الاحتجاج، بل من الغيظ، بل من الخوف، بل من الشوق، بل من الغيرة، بل من الانتقام. في كل شيء أظهرتم أنفسكم أنكم أبرياء في هذا الأمر.","إذا وإن كنت قد كتبت إليكم، فليس لأجل المذنب ولا لأجل المذنب إليه، بل لكي يظهر لكم أمام االله اجتهادنا لأجلكم.","من أجل هذا قد تعزينا بتعزيتكم. ولكن فرحنا أكثر جدا بسبب فرح تيطس، لأن روحه قد استراحت بكم جميعا.","فإني إن كنت افتخرت شيئا لديه من جهتكم لم أخجل، بل كما كلمناكم بكل شيء بالصدق، كذلك افتخارنا أيضا لدى تيطس صار صادقا.","وأحشاؤه هي نحوكم بالزيادة، متذكرا طاعة جميعكم، كيف قبلتموه بخوف ورعدة.","أنا أفرح إذا أني أثق بكم في كل شيء."],["ثم نعرفكم أيها الإخوة نعمة االله المعطاة في كنائس مكدونية،","أنه في اختبار ضيقة شديدة فاض وفور فرحهم وفقرهم العميق لغنى سخائهم،","لأنهم أعطوا حسب الطاقة، أنا أشهد، وفوق الطاقة، من تلقاء أنفسهم،","ملتمسين منا، بطلبة كثيرة، أن نقبل النعمة وشركة الخدمة التي للقديسين.","وليس كما رجونا، بل أعطوا أنفسهم أولا للرب، ولنا، بمشيئة االله.","حتى إننا طلبنا من تيطس أنه كما سبق فابتدأ، كذلك يتمم لكم هذه النعمة أيضا.","لكن كما تزدادون في كل شيء: في الإيمان والكلام والعلم وكل اجتهاد ومحبتكم لنا، ليتكم تزدادون في هذه النعمة أيضا.","لست أقول على سبيل الأمر، بل باجتهاد آخرين، مختبرا إخلاص محبتكم أيضا.","فإنكم تعرفون نعمة ربنا يسوع المسيح، أنه من أجلكم افتقر وهو غني، لكي تستغنوا أنتم بفقره.","أعطي رأيا في هذا أيضا، لأن هذا ينفعكم أنتم الذين سبقتم فابتدأتم منذ العام الماضي، ليس أن تفعلوا فقط بل أن تريدوا أيضا.","ولكن الآن تمموا العمل أيضا، حتى إنه كما أن النشاط للإرادة، كذلك يكون التتميم أيضا حسب ما لكم.","لأنه إن كان النشاط موجودا فهو مقبول على حسب ما للإنسان، لا على حسب ما ليس له.","فإنه ليس لكي يكون للآخرين راحة ولكم ضيق،","بل بحسب المساواة. لكي تكون في هذا الوقت فضالتكم لإعوازهم، كي تصير فضالتهم لإعوازكم، حتى تحصل المساواة.","كما هو مكتوب: »الذي جمع كثيرا لم يفضل، والذي جمع قليلا لم ينقص«.","ولكن شكرا لله الذي جعل هذا الاجتهاد عينه لأجلكم في قلب تيطس،","لأنه قبل الطلبة. وإذ كان أكثر اجتهادا مضى إليكم من تلقاء نفسه.","وأرسلنا معه الأخ الذي مدحه في الإنجيل في جميع الكنائس.","وليس ذلك فقط، بل هو منتخب أيضا من الكنائس رفيقا لنا في السفر، مع هذه النعمة المخدومة منا لمجد ذات الرب الواحد، ولنشاطكم.","متجنبين هذا أن يلومنا أحد في جسامة هذه المخدومة منا.","معتنين بأمور حسنة، ليس قدام الرب فقط، بل قدام الناس أيضا.","وأرسلنا معهما أخانا، الذي اختبرنا مرارا في أمور كثيرة أنه مجتهد، ولكنه الآن أشد اجتهادا كثيرا بالثقة الكثيرة بكم.","أما من جهة تيطس فهو شريك لي وعامل معي لأجلكم. وأما أخوانا فهما رسولا الكنائس، ومجد المسيح.","فبينوا لهم، وقدام الكنائس، بينة محبتكم، وافتخارنا من جهتكم"],["فإنه من جهة الخدمة للقديسين هو فضول مني أن أكتب إليكم.","لأني أعلم نشاطكم الذي أفتخر به من جهتكم لدى المكدونيين، أن أخائية مستعدة منذ العام الماضي. وغيرتكم قد حرضت الأكثرين.","ولكن أرسلت الإخوة لئلا يتعطل افتخارنا من جهتكم من هذا القبيل، كي تكونوا مستعدين كما قلت.","حتى إذا جاء معي مكدونيون ووجدوكم غير مستعدين لا نخجل نحن - حتى لا أقول أنتم - في جسارة الافتخار هذه.","فرأيت لازما أن أطلب إلى الإخوة أن يسبقوا إليكم، ويهيئوا قبلا بركتكم التي سبق التخبير بها، لتكون هي معدة هكذا كأنها بركة، لا كأنها بخل.","هذا وإن من يزرع بالشح فبالشح أيضا يحصد، ومن يزرع بالبركات فبالبركات أيضا يحصد.","كل واحد كما ينوي بقلبه، ليس عن حزن أو اضطرار. لأن المعطي المسرور يحبه االله.","والله قادر أن يزيدكم كل نعمة، لكي تكونوا ولكم كل اكتفاء كل حين في كل شيء، تزدادون في كل عمل صالح.","كما هو مكتوب: »فرق. أعطى المساكين. بره يبقى إلى الأبد«.","والذي يقدم بذارا للزارع وخبزا للأكل، سيقدم ويكثر بذاركم وينمي غلات بركم.","مستغنين في كل شيء لكل سخاء ينشئ بنا شكرا لله.","لأن افتعال هذه الخدمة ليس يسد إعواز القديسين فقط، بل يزيد بشكر كثير لله","إذ هم باختبار هذه الخدمة يمجدون االله على طاعة اعترافكم لإنجيل المسيح، وسخاء التوزيع لهم وللجميع.","وبدعائهم لأجلكم، مشتاقين إليكم من أجل نعمة االله الفائقة لديكم.","فشكرا لله على عطيته التي لا يعبر عنها."],["ثم أطلب إليكم بوداعة المسيح وحلمه، أنا نفسي بولس الذي في الحضرة ذليل بينكم، وأما في الغيبة فمتجاسر عليكم.","ولكن أطلب أن لا أتجاسر وأنا حاضر بالثقة التي بها أرى أني سأجترئ على قوم يحسبوننا كأننا نسلك حسب الجسد.","لأننا وإن كنا نسلك في الجسد، لسنا حسب الجسد نحارب.","إذ أسلحة محاربتنا ليست جسدية، بل قادرة بالله على هدم حصون.","هادمين ظنونا وكل علو يرتفع ضد معرفة االله، ومستأسرين كل فكر إلى طاعة المسيح،","ومستعدين لأن ننتقم على كل عصيان، متى كملت طاعتكم.","أتنظرون إلى ما هو حسب الحضرة؟ إن وثق أحد بنفسه أنه للمسيح، فليحسب هذا أيضا من نفسه: أنه كما هو للمسيح، كذلك نحن أيضا للمسيح!","فإني وإن افتخرت شيئا أكثر بسلطاننا الذي أعطانا إياه الرب لبنيانكم لا لهدمكم، لا أخجل.","لئلا أظهر كأني أخيفكم بالرسائل.","لأنه يقول: »الرسائل ثقيلة وقوية، وأما حضور الجسد فضعيف والكلام حقير«.","مثل هذا فليحسب أننا كما نحن في الكلام بالرسائل ونحن غائبون، هكذا نكون أيضا بالفعل ونحن حاضرون.","لأننا لا نجترئ أن نعد أنفسنا بين قوم من الذين يمدحون أنفسهم، ولا أن نقابل أنفسنا بهم. بل هم إذ يقيسون أنفسهم على أنفسهم، ويقابلون أنفسهم بأنفسهم، لا يفهمون.","ولكن نحن لا نفتخر إلى ما لا يقاس، بل حسب قياس القانون الذي قسمه لنا االله، قياسا للبلوغ إليكم أيضا.","لأننا لا نمدد أنفسنا كأننا لسنا نبلغ إليكم. إذ قد وصلنا إليكم أيضا في إنجيل المسيح.","غير مفتخرين إلى ما لا يقاس في أتعاب آخرين، بل راجين إذا نما إيمانكم أن نتعظم بينكم حسب قانوننا بزيادة،","لنبشر إلى ما وراءكم. لا لنفتخر بالأمور المعدة في قانون غيرنا.","وأما من افتخر فليفتخر بالرب.","لأنه ليس من مدح نفسه هو المزكى، بل من يمدحه الرب."],["ليتكم تحتملون غباوتي قليلا! بل أنتم محتملي.","فإني أغار عليكم غيرة االله، لأني خطبتكم لرجل واحد، لأقدم عذراء عفيفة للمسيح.","ولكنني أخاف أنه كما خدعت الحية حواء بمكرها، هكذا تفسد أذهانكم عن البساطة التي في المسيح.","فإنه إن كان الآتي يكرز بيسوع آخر لم نكرز به، أو كنتم تأخذون روحا آخر لم تأخذوه، أو إنجيلا آخر لم تقبلوه، فحسنا كنتم تحتملون.","لأني أحسب أني لم أنقص شيئا عن فائقي الرسل.","وإن كنت عاميا في الكلام فلست في العلم، بل نحن في كل شيء ظاهرون لكم بين الجميع.","أم أخطأت خطية إذ أذللت نفسي كي ترتفعوا أنتم، لأني بشرتكم مجانا بإنجيل االله؟","سلبت كنائس أخرى آخذا أجرة لأجل خدمتكم، وإذ كنت حاضرا عندكم واحتجت، لم أثقل على أحد.","لأن احتياجي سده الإخوة الذين أتوا من مكدونية. وفي كل شيء حفظت نفسي غير ثقيل عليكم، وسأحفظها.","حق المسيح في. إن هذا الافتخار لا يسد عني في أقاليم أخائية.","لماذا؟ ألأني لا أحبكم؟ الله يعلم.","ولكن ما أفعله سأفعله لأقطع فرصة الذين يريدون فرصة كي يوجدوا كما نحن أيضا في ما يفتخرون به.","لأن مثل هؤلاء هم رسل كذبة، فعلة ماكرون، مغيرون شكلهم إلى شبه رسل المسيح.","ولا عجب. لأن الشيطان نفسه يغير شكله إلى شبه ملاك نور!","فليس عظيما إن كان خدامه أيضا يغيرون شكلهم كخدام للبر. الذين نهايتهم تكون حسب أعمالهم.","أقول أيضا: لا يظن أحد أني غبي. وإلا فاقبلوني ولو كغبي، لأفتخر أنا أيضا قليلا.","الذي أتكلم به لست أتكلم به بحسب الرب، بل كأنه في غباوة، في جسارة الافتخار هذه.","بما أن كثيرين يفتخرون حسب الجسد أفتخر أنا أيضا.","فإنكم بسرور تحتملون الأغبياء، إذ أنتم عقلاء!","لأنكم تحتملون إن كان أحد يستعبدكم! إن كان أحد يأكلكم! إن كان أحد يأخذكم! إن كان أحد يرتفع! إن كان أحد يضربكم على وجوهكم!","على سبيل الهوان أقول كيف أننا كنا ضعفاء. ولكن الذي يجترئ فيه أحد، أقول في غباوة: أنا أيضا أجترئ فيه.","أهم عبرانيون؟ فأنا أيضا. أهم إسرائيليون؟ فأنا أيضا. أهم نسل إبراهيم؟ فأنا أيضا.","أهم خدام المسيح؟ أقول كمختل العقل: فأنا أفضل. في الأتعاب أكثر. في الضربات أوفر. في السجون أكثر. في الميتات مرارا كثيرة.","من اليهود خمس مرات قبلت أربعين جلدة إلا واحدة.","ثلاث مرات ضربت بالعصي. مرة رجمت. ثلاث مرات انكسرت بي السفينة. ليلا ونهارا قضيت في العمق.","بأسفار مرارا كثيرة. بأخطار سيول. بأخطار لصوص. بأخطار من جنسي. بأخطار من الأمم. بأخطار في المدينة. بأخطار في البرية. بأخطار في البحر. بأخطار من إخوة كذبة.","في تعب وكد. في أسهار مرارا كثيرة. في جوع وعطش. في أصوام مرارا كثيرة. في برد وعري.","عدا ما هو دون ذلك: التراكم علي كل يوم. الاهتمام بجميع الكنائس.","من يضعف وأنا لا أضعف؟ من يعثر وأنا لا ألتهب؟","إن كان يجب الافتخار، فسأفتخر بأمور ضعفي.","الله أبو ربنا يسوع المسيح، الذي هو مبارك إلى الأبد، يعلم أني لست أكذب.","في دمشق والي الحارث الملك كان يحرس مدينة الدمشقيين يريد أن يمسكني،","فتدليت من طاقة في زنبيل من السور، ونجوت من يديه."],["إنه لا يوافقني أن أفتخر. فإني آتي إلى مناظر الرب وإعلاناته.","أعرف إنسانا في المسيح قبل أربع عشرة سنة. أفي الجسد؟ لست أعلم، أم خارج الجسد؟ لست أعلم. االله يعلم. اختطف هذا إلى السماء الثالثة.","وأعرف هذا الإنسان. أفي الجسد أم خارج الجسد؟ لست أعلم. االله يعلم.","أنه اختطف إلى الفردوس، وسمع كلمات لا ينطق بها، ولا يسوغ لإنسان أن يتكلم بها.","من جهة هذا أفتخر. ولكن من جهة نفسي لا أفتخر إلا بضعفاتي.","فإني إن أردت أن أفتخر لا أكون غبيا، لأني أقول الحق. ولكني أتحاشى لئلا يظن أحد من جهتي فوق ما يراني أو يسمع مني.","ولئلا أرتفع بفرط الإعلانات، أعطيت شوكة في الجسد، ملاك الشيطان، ليلطمني لئلا أرتفع.","من جهة هذا تضرعت إلى الرب ثلاث مرات أن يفارقني.","فقال لي: »تكفيك نعمتي، لأن قوتي في الضعف تكمل«. فبكل سرور أفتخر بالحري في ضعفاتي، لكي تحل علي قوة المسيح.","لذلك أسر بالضعفات والشتائم والضرورات والاضطهادات والضيقات لأجل المسيح. لأني حينما أنا ضعيف فحينئذ أنا قوي.","قد صرت غبيا وأنا أفتخر. أنتم ألزمتموني! لأنه كان ينبغي أن أمدح منكم، إذ لم أنقص شيئا عن فائقي الرسل، وإن كنت لست شيئا.","إن علامات الرسول صنعت بينكم في كل صبر، بآيات وعجائب وقوات.","لأنه ما هو الذي نقصتم عن سائر الكنائس، إلا أني أنا لم أثقل عليكم؟ سامحوني بهذا الظلم.","هوذا المرة الثالثة أنا مستعد أن آتي إليكم ولا أثقل عليكم. لأني لست أطلب ما هو لكم بل إياكم. لأنه لا ينبغي أن الأولاد يذخرون للوالدين بل الوالدون للأولاد.","وأما أنا فبكل سرور أنفق وأنفق لأجل أنفسكم، وإن كنت كلما أحبكم أكثر أحب أقل!","فليكن. أنا لم أثقل عليكم. لكن إذ كنت محتالا أخذتكم بمكر!","هل طمعت فيكم بأحد من الذين أرسلتهم إليكم؟","طلبت إلى تيطس وأرسلت معه الأخ. هل طمع فيكم تيطس؟ أما سلكنا بذات الروح الواحد؟ أما بذات الخطوات الواحدة؟","أتظنون أيضا أننا نحتج لكم؟ أمام االله في المسيح نتكلم. ولكن الكل أيها الأحباء لأجل بنيانكم.","لأني أخاف إذا جئت أن لا أجدكم كما أريد، وأوجد منكم كما لا تريدون. أن توجد خصومات ومحاسدات وسخطات وتحزبات ومذمات ونميمات وتكبرات وتشويشات -","أن يذلني إلهي عندكم، إذا جئت أيضا وأنوح على كثيرين من الذين أخطأوا من قبل ولم يتوبوا عن النجاسة والزنا والعهارة التي فعلوها."],["هذه المرة الثالثة آتي إليكم. على فم شاهدين وثلاثة تقوم كل كلمة.","قد سبقت فقلت، وأسبق فأقول كما وأنا حاضر المرة الثانية، وأنا غائب الآن، أكتب للذين أخطأوا من قبل، ولجميع الباقين: أني إذا جئت أيضا لا أشفق.","إذ أنتم تطلبون برهان المسيح المتكلم في، الذي ليس ضعيفا لكم بل قوي فيكم.","لأنه وإن كان قد صلب من ضعف لكنه حي بقوة االله. فنحن أيضا ضعفاء فيه، لكننا سنحيا معه بقوة االله من جهتكم.","جربوا أنفسكم، هل أنتم في الإيمان؟ امتحنوا أنفسكم. أم لستم تعرفون أنفسكم أن يسوع المسيح هو فيكم، إن لم تكونوا مرفوضين؟","لكنني أرجو أنكم ستعرفون أننا نحن لسنا مرفوضين.","وأصلي إلى االله أنكم لا تعملون شيئا رديا، ليس لكي نظهر نحن مزكين، بل لكي تصنعوا أنتم حسنا، ونكون نحن كأننا مرفوضون.","لأننا لا نستطيع شيئا ضد الحق بل لأجل الحق.","لأننا نفرح حينما نكون نحن ضعفاء وأنتم تكونون أقوياء. وهذا أيضا نطلبه كما لكم.","لذلك أكتب بهذا وأنا غائب، لكي لا أستعمل جزما وأنا حاضر، حسب السلطان الذي أعطاني إياه الرب للبنيان لا للهدم.","أخيرا أيها الإخوة افرحوا. اكملوا. تعزوا. اهتموا اهتماما واحدا. عيشوا بالسلام، وإله المحبة والسلام سيكون معكم.","سلموا بعضكم على بعض بقبلة مقدسة.","يسلم عليكم جميع القديسين.","نعمة ربنا يسوع المسيح، ومحبة االله، وشركة الروح القدس مع جميعكم. آمين. رسالة بولس الرسول إلى أهل غلاطية"]];
BBD["غلاطية"]=[["بولس، رسول لا من الناس ولا بإنسان، بل بيسوع المسيح واالله الآب الذي أقامه من الأموات،","وجميع الإخوة الذين معي، إلى كنائس غلاطية.","نعمة لكم وسلام من االله الآب، ومن ربنا يسوع المسيح،","الذي بذل نفسه لأجل خطايانا، لينقذنا من العالم الحاضر الشرير حسب إرادة االله وأبينا،","الذي له المجد إلى أبد الآبدين. آمين.","إني أتعجب أنكم تنتقلون هكذا سريعا عن الذي دعاكم بنعمة المسيح إلى إنجيل آخر.","ليس هو آخر، غير أنه يوجد قوم يزعجونكم ويريدون أن يحولوا إنجيل المسيح.","ولكن إن بشرناكم نحن أو ملاك من السماء بغير ما بشرناكم، فليكن »أناثيما«.","كما سبقنا فقلنا أقول الآن أيضا: إن كان أحد يبشركم بغير ما قبلتم، فليكن »أناثيما«.","أفأستعطف الآن الناس أم االله؟ أم أطلب أن أرضي الناس؟ فلو كنت بعد أرضي الناس لم أكن عبدا للمسيح.","وأعرفكم أيها الإخوة الإنجيل الذي بشرت به، أنه ليس بحسب إنسان.","لأني لم أقبله من عند إنسان ولا علمته. بل بإعلان يسوع المسيح.","فإنكم سمعتم بسيرتي قبلا في الديانة اليهودية، أني كنت أضطهد كنيسة االله بإفراط وأتلفها.","وكنت أتقدم في الديانة اليهودية على كثيرين من أترابي في جنسي، إذ كنت أوفر غيرة في تقليدات آبائي.","ولكن لما سر االله الذي أفرزني من بطن أمي، ودعاني بنعمته","أن يعلن ابنه في لأبشر به بين الأمم، للوقت لم أستشر لحما ودما","ولا صعدت إلى أورشليم إلى الرسل الذين قبلي، بل انطلقت إلى العربية، ثم رجعت أيضا إلى دمشق.","ثم بعد ثلاث سنين صعدت إلى أورشليم لأتعرف ببطرس، فمكثت عنده خمسة عشر يوما.","ولكنني لم أر غيره من الرسل إلا يعقوب أخا الرب.","والذي أكتب به إليكم هوذا قدام االله أني لست أكذب فيه.","وبعد ذلك جئت إلى أقاليم سورية وكيليكية.","ولكنني كنت غير معروف بالوجه عند كنائس اليهودية التي في المسيح.","غير أنهم كانوا يسمعون أن الذي كان يضطهدنا قبلا، يبشر الآن بالإيمان الذي كان قبلا يتلفه.","فكانوا يمجدون االله في."],["ثم بعد أربع عشرة سنة صعدت أيضا إلى أورشليم مع برنابا، آخذا معي تيطس أيضا.","وإنما صعدت بموجب إعلان، وعرضت عليهم الإنجيل الذي أكرز به بين الأمم، ولكن بالانفراد على المعتبرين، لئلا أكون أسعى أو قد سعيت باطلا.","لكن لم يضطر ولا تيطس الذي كان معي، وهو يوناني، أن يختتن.","ولكن بسبب الإخوة الكذبة المدخلين خفية، الذين دخلوا اختلاسا ليتجسسوا حريتنا التي لنا في المسيح كي يستعبدونا -","الذين لم نذعن لهم بالخضوع ولا ساعة، ليبقى عندكم حق الإنجيل.","وأما المعتبرون أنهم شيء، مهما كانوا، لا فرق عندي: االله لا يأخذ بوجه إنسان - فإن هؤلاء المعتبرين لم يشيروا علي بشيء.","بل بالعكس، إذ رأوا أني اؤتمنت على إنجيل الغرلة كما بطرس على إنجيل الختان.","فإن الذي عمل في بطرس لرسالة الختان عمل في أيضا للأمم.","فإذ علم بالنعمة المعطاة لي يعقوب وصفا ويوحنا، المعتبرون أنهم أعمدة، أعطوني وبرنابا يمين الشركة لنكون نحن للأمم وأما هم فللختان.","غير أن نذكر الفقراء. وهذا عينه كنت اعتنيت أن أفعله.","ولكن لما أتى بطرس إلى أنطاكية قاومته مواجهة، لأنه كان ملوما.","لأنه قبلما أتى قوم من عند يعقوب كان يأكل مع الأمم، ولكن لما أتوا كان يؤخر ويفرز نفسه، خائفا من الذين هم من الختان.","وراءى معه باقي اليهود أيضا، حتى إن برنابا أيضا انقاد إلى ريائهم!","لكن لما رأيت أنهم لا يسلكون باستقامة حسب حق الإنجيل، قلت لبطرس قدام الجميع: »إن كنت وأنت يهودي تعيش أمميا لا يهوديا، فلماذا تلزم الأمم أن يتهودوا؟«","نحن بالطبيعة يهود ولسنا من الأمم خطاة،","إذ نعلم أن الإنسان لا يتبرر بأعمال الناموس، بل بإيمان يسوع المسيح، آمنا نحن أيضا بيسوع المسيح، لنتبرر بإيمان يسوع لا بأعمال الناموس. لأنه بأعمال الناموس لا يتبرر جسد ما.","فإن كنا ونحن طالبون أن نتبرر في المسيح نوجد نحن أنفسنا أيضا خطاة، أفالمسيح خادم للخطية؟ حاشا!","فإني إن كنت أبني أيضا هذا الذي قد هدمته، فإني أظهر نفسي متعديا.","لأني مت بالناموس للناموس لأحيا لله.","مع المسيح صلبت، فأحيا لا أنا بل المسيح يحيا في. فما أحياه الآن في الجسد فإنما أحياه في الإيمان، إيمان ابن االله، الذي أحبني وأسلم نفسه لأجلي.","لست أبطل نعمة االله. لأنه إن كان بالناموس بر، فالمسيح إذا مات بلا سبب."],["أيها الغلاطيون الأغبياء، من رقاكم حتى لا تذعنوا للحق؟ أنتم الذين أمام عيونكم قد رسم يسوع المسيح بينكم مصلوبا!","أريد أن أتعلم منكم هذا فقط: أبأعمال الناموس أخذتم الروح أم بخبر الإيمان؟","أهكذا أنتم أغبياء! أبعدما ابتدأتم بالروح تكملون الآن بالجسد؟","أهذا المقدار احتملتم عبثا؟ إن كان عبثا!","فالذي يمنحكم الروح، ويعمل قوات فيكم، أبأعمال الناموس أم بخبر الإيمان؟","كما »آمن إبراهيم باالله فحسب له برا«.","اعلموا إذا أن الذين هم من الإيمان أولئك هم بنو إبراهيم.","والكتاب إذ سبق فرأى أن االله بالإيمان يبرر الأمم، سبق فبشر إبراهيم أن »فيك تتبارك جميع الأمم«.","إذا الذين هم من الإيمان يتباركون مع إبراهيم المؤمن.","لأن جميع الذين هم من أعمال الناموس هم تحت لعنة، لأنه مكتوب »ملعون كل من لا يثبت في جميع ما هو مكتوب في كتاب الناموس ليعمل به«.","ولكن أن ليس أحد يتبرر بالناموس عند االله فظاهر، لأن »البار بالإيمان يحيا«.","ولكن الناموس ليس من الإيمان، بل »الإنسان الذي يفعلها سيحيا بها«.","المسيح افتدانا من لعنة الناموس، إذ صار لعنة لأجلنا، لأنه مكتوب: »ملعون كل من علق على خشبة«.","لتصير بركة إبراهيم للأمم في المسيح يسوع، لننال بالإيمان موعد الروح،","أيها الإخوة بحسب الإنسان أقول »ليس أحد يبطل عهدا قد تمكن ولو من إنسان، أو يزيد عليه«.","وأما المواعيد فقيلت في »إبراهيم وفي نسله«. لا يقول »وفي الأنسال« كأنه عن كثيرين، بل كأنه عن واحد. و»في نسلك« الذي هو المسيح.","وإنما أقول هذا: إن الناموس الذي صار بعد أربعمئة وثلاثين سنة، لا ينسخ عهدا قد سبق فتمكن من االله نحو المسيح حتى يبطل الموعد.","لأنه إن كانت الوراثة من الناموس فلم تكن أيضا من موعد. ولكن االله وهبها لإبراهيم بموعد.","فلماذا الناموس؟ قد زيد بسبب التعديات، إلى أن يأتي النسل الذي قد وعد له، مرتبا بملائكة في يد وسيط.","وأما الوسيط فلا يكون لواحد. ولكن االله واحد.","فهل الناموس ضد مواعيد االله؟ حاشا! لأنه لو أعطي ناموس قادر أن يحيي، لكان بالحقيقة البر بالناموس.","لكن الكتاب أغلق على الكل تحت الخطية، ليعطى الموعد من إيمان يسوع المسيح للذين يؤمنون.","ولكن قبلما جاء الإيمان كنا محروسين تحت الناموس، مغلقا علينا إلى الإيمان العتيد أن يعلن.","إذا قد كان الناموس مؤدبنا إلى المسيح، لكي نتبرر بالإيمان.","ولكن بعد ما جاء الإيمان لسنا بعد تحت مؤدب.","لأنكم جميعا أبناء االله بالإيمان بالمسيح يسوع.","لأن كلكم الذين اعتمدتم بالمسيح قد لبستم المسيح.","ليس يهودي ولا يوناني. ليس عبد ولا حر. ليس ذكر وأنثى، لأنكم جميعا واحد في المسيح يسوع.","فإن كنتم للمسيح فأنتم إذا نسل إبراهيم، وحسب الموعد ورثة."],["وإنما أقول: ما دام الوارث قاصرا لا يفرق شيئا عن العبد، مع كونه صاحب الجميع.","بل هو تحت أوصياء ووكلاء إلى الوقت المؤجل من أبيه.","هكذا نحن أيضا: لما كنا قاصرين كنا مستعبدين تحت أركان العالم.","ولكن لما جاء ملء الزمان، أرسل االله ابنه مولودا من امرأة، مولودا تحت الناموس،","ليفتدي الذين تحت الناموس، لننال التبني.","ثم بما أنكم أبناء، أرسل االله روح ابنه إلى قلوبكم صارخا: »يا أبا الآب«.","إذا لست بعد عبدا بل ابنا، وإن كنت ابنا فوارث لله بالمسيح.","لكن حينئذ إذ كنتم لا تعرفون االله استعبدتم للذين ليسوا بالطبيعة آلهة.","وأما الآن إذ عرفتم االله، بل بالحري عرفتم من االله، فكيف ترجعون أيضا إلى الأركان الضعيفة الفقيرة التي تريدون أن تستعبدوا لها من جديد؟","أتحفظون أياما وشهورا وأوقاتا وسنين؟","أخاف عليكم أن أكون قد تعبت فيكم عبثا!","أتضرع إليكم أيها الإخوة، كونوا كما أنا لأني أنا أيضا كما أنتم. لم تظلموني شيئا.","ولكنكم تعلمون أني بضعف الجسد بشرتكم في الأول.","وتجربتي التي في جسدي لم تزدروا بها ولا كرهتموها، بل كملاك من االله قبلتموني، كالمسيح يسوع.","فماذا كان إذا تطويبكم؟ لأني أشهد لكم أنه لو أمكن لقلعتم عيونكم وأعطيتموني.","أفقد صرت إذا عدوا لكم لأني أصدق لكم؟","يغارون لكم ليس حسنا، بل يريدون أن يصدوكم لكي تغاروا لهم.","حسنة هي الغيرة في الحسنى كل حين، وليس حين حضوري عندكم فقط.","يا أولادي الذين أتمخض بكم أيضا إلى أن يتصور المسيح فيكم.","ولكني كنت أريد أن أكون حاضرا عندكم الآن وأغير صوتي، لأني متحير فيكم!","قولوا لي، أنتم الذين تريدون أن تكونوا تحت الناموس، ألستم تسمعون الناموس؟","فإنه مكتوب أنه كان لإبراهيم ابنان، واحد من الجارية والآخر من الحرة.","لكن الذي من الجارية ولد حسب الجسد، وأما الذي من الحرة فبالموعد.","وكل ذلك رمز، لأن هاتين هما العهدان، أحدهما من جبل سيناء الوالد للعبودية، الذي هو هاجر.","لأن هاجر جبل سيناء في العربية. ولكنه يقابل أورشليم الحاضرة، فإنها مستعبدة مع بنيها.","وأما أورشليم العليا، التي هي أمنا جميعا، فهي حرة.","لأنه مكتوب: »افرحي أيتها العاقر التي لم تلد. اهتفي واصرخي أيتها التي لم تتمخض، فإن أولاد الموحشة أكثر من التي لها زوج«.","وأما نحن أيها الإخوة فنظير إسحاق، أولاد الموعد.","ولكن كما كان حينئذ الذي ولد حسب الجسد يضطهد الذي حسب الروح، هكذا الآن أيضا.","لكن ماذا يقول الكتاب؟ »اطرد الجارية وابنها، لأنه لا يرث ابن الجارية مع ابن الحرة«.","إذا أيها الإخوة لسنا أولاد جارية بل أولاد الحرة."],["فاثبتوا إذا في الحرية التي قد حررنا المسيح بها، ولا ترتبكوا أيضا بنير عبودية.","ها أنا بولس أقول لكم: إنه إن اختتنتم لا ينفعكم المسيح شيئا!","لكن أشهد أيضا لكل إنسان مختتن أنه ملتزم أن يعمل بكل الناموس.","قد تبطلتم عن المسيح أيها الذين تتبررون بالناموس. سقطتم من النعمة.","فإننا بالروح من الإيمان نتوقع رجاء بر.","لأنه في المسيح يسوع لا الختان ينفع شيئا ولا الغرلة، بل الإيمان العامل بالمحبة.","كنتم تسعون حسنا. فمن صدكم حتى لا تطاوعوا للحق؟","هذه المطاوعة ليست من الذي دعاكم.","خميرة صغيرة تخمر العجين كله.","ولكنني أثق بكم في الرب أنكم لا تفتكرون شيئا آخر. ولكن الذي يزعجكم سيحمل الدينونة أي من كان.","وأما أنا أيها الإخوة فإن كنت بعد أكرز بالختان فلماذا أضطهد بعد؟ إذا عثرة الصليب قد بطلت.","يا ليت الذين يقلقونكم يقطعون أيضا!","فإنكم إنما دعيتم للحرية أيها الإخوة. غير أنه لا تصيروا الحرية فرصة للجسد، بل بالمحبة اخدموا بعضكم بعضا.","لأن كل الناموس في كلمة واحدة يكمل: »تحب قريبك كنفسك«.","فإذا كنتم تنهشون وتأكلون بعضكم بعضا، فانظروا لئلا تفنوا بعضكم بعضا.","وإنما أقول: اسلكوا بالروح فلا تكملوا شهوة الجسد.","لأن الجسد يشتهي ضد الروح والروح ضد الجسد، وهذان يقاوم أحدهما الآخر، حتى تفعلون ما لا تريدون.","ولكن إذا انقدتم بالروح فلستم تحت الناموس.","وأعمال الجسد ظاهرة: التي هي زنى عهارة نجاسة دعارة","عبادة الأوثان سحر عداوة خصام غيرة سخط تحزب شقاق بدعة","حسد قتل سكر بطر، وأمثال هذه التي أسبق فأقول لكم عنها كما سبقت فقلت أيضا: إن الذين يفعلون مثل هذه لا يرثون ملكوت االله.","وأما ثمر الروح فهو: محبة فرح سلام، طول أناة لطف صلاح، إيمان","وداعة تعفف. ضد أمثال هذه ليس ناموس.","ولكن الذين هم للمسيح قد صلبوا الجسد مع الأهواء والشهوات.","إن كنا نعيش بالروح فلنسلك أيضا بحسب الروح.","لا نكن معجبين نغاضب بعضنا بعضا، ونحسد بعضنا بعضا."],["أيها الإخوة، إن انسبق إنسان فأخذ في زلة ما، فأصلحوا أنتم الروحانيين مثل هذا بروح الوداعة، ناظرا إلى نفسك لئلا تجرب أنت أيضا.","احملوا بعضكم أثقال بعض وهكذا تمموا ناموس المسيح.","لأنه إن ظن أحد أنه شيء وهو ليس شيئا، فإنه يغش نفسه.","ولكن ليمتحن كل واحد عمله، وحينئذ يكون له الفخر من جهة نفسه فقط، لا من جهة غيره.","لأن كل واحد سيحمل حمل نفسه.","ولكن ليشارك الذي يتعلم الكلمة المعلم في جميع الخيرات.","لا تضلوا! االله لا يشمخ عليه. فإن الذي يزرعه الإنسان إياه يحصد أيضا.","لأن من يزرع لجسده فمن الجسد يحصد فسادا، ومن يزرع للروح فمن الروح يحصد حياة أبدية.","فلا نفشل في عمل الخير لأننا سنحصد في وقته إن كنا لا نكل.","فإذا حسبما لنا فرصة فلنعمل الخير للجميع، ولا سيما لأهل الإيمان.","انظروا، ما أكبر الأحرف التي كتبتها إليكم بيدي!","جميع الذين يريدون أن يعملوا منظرا حسنا في الجسد، هؤلاء يلزمونكم أن تختتنوا، لئلا يضطهدوا لأجل صليب المسيح فقط.","لأن الذين يختتنون هم لا يحفظون الناموس، بل يريدون أن تختتنوا أنتم لكي يفتخروا في جسدكم.","وأما من جهتي، فحاشا لي أن أفتخر إلا بصليب ربنا يسوع المسيح، الذي به قد صلب العالم لي وأنا للعالم.","لأنه في المسيح يسوع ليس الختان ينفع شيئا ولا الغرلة، بل الخليقة الجديدة.","فكل الذين يسلكون بحسب هذا القانون عليهم سلام ورحمة، وعلى إسرائيل االله.","في ما بعد لا يجلب أحد علي أتعابا، لأني حامل في جسدي سمات الرب يسوع.","نعمة ربنا يسوع المسيح مع روحكم أيها الإخوة. آمين. رسالة بولس الرسول إلى أهل أفسس"]];
BBD["أفسس"]=[["بولس، رسول يسوع المسيح بمشيئة االله، إلى القديسين الذين في أفسس، والمؤمنين في المسيح يسوع.","نعمة لكم وسلام من االله أبينا والرب يسوع المسيح.","مبارك االله أبو ربنا يسوع المسيح، الذي باركنا بكل بركة روحية في السماويات في المسيح،","كما اختارنا فيه قبل تأسيس العالم، لنكون قديسين وبلا لوم قدامه في المحبة،","إذ سبق فعيننا للتبني بيسوع المسيح لنفسه، حسب مسرة مشيئته،","لمدح مجد نعمته التي أنعم بها علينا في المحبوب،","الذي فيه لنا الفداء، بدمه غفران الخطايا، حسب غنى نعمته،","التي أجزلها لنا بكل حكمة وفطنة،","إذ عرفنا بسر مشيئته، حسب مسرته التي قصدها في نفسه،","لتدبير ملء الأزمنة، ليجمع كل شيء في المسيح، ما في السماوات وما على الأرض، في ذاك","الذي فيه أيضا نلنا نصيبا، معينين سابقا حسب قصد الذي يعمل كل شيء حسب رأي مشيئته،","لنكون لمدح مجده، نحن الذين قد سبق رجاؤنا في المسيح.","الذي فيه أيضا أنتم، إذ سمعتم كلمة الحق، إنجيل خلاصكم، الذي فيه أيضا إذ آمنتم ختمتم بروح الموعد القدوس،","الذي هو عربون ميراثنا، لفداء المقتنى، لمدح مجده.","لذلك أنا أيضا إذ قد سمعت بإيمانكم بالرب يسوع، ومحبتكم نحو جميع القديسين،","لا أزال شاكرا لأجلكم، ذاكرا إياكم في صلواتي،","كي يعطيكم إله ربنا يسوع المسيح، أبو المجد، روح الحكمة والإعلان في معرفته،","مستنيرة عيون أذهانكم، لتعلموا ما هو رجاء دعوته، وما هو غنى مجد ميراثه في القديسين،","وما هي عظمة قدرته الفائقة نحونا نحن المؤمنين، حسب عمل شدة قوته","الذي عمله في المسيح، إذ أقامه من الأموات، وأجلسه عن يمينه في السماويات،","فوق كل رياسة وسلطان وقوة وسيادة، وكل اسم يسمى ليس في هذا الدهر فقط بل في المستقبل أيضا،","وأخضع كل شيء تحت قدميه، وإياه جعل رأسا فوق كل شيء للكنيسة،","التي هي جسده، ملء الذي يملأ الكل في الكل."],["وأنتم إذ كنتم أمواتا بالذنوب والخطايا،","التي سلكتم فيها قبلا حسب دهر هذا العالم، حسب رئيس سلطان الهواء، الروح الذي يعمل الآن في أبناء المعصية،","الذين نحن أيضا جميعا تصرفنا قبلا بينهم في شهوات جسدنا، عاملين مشيئات الجسد والأفكار، وكنا بالطبيعة أبناء الغضب كالباقين أيضا،","االله الذي هو غني في الرحمة، من أجل محبته الكثيرة التي أحبنا بها،","ونحن أموات بالخطايا أحيانا مع المسيح - بالنعمة أنتم مخلصون -","وأقامنا معه، وأجلسنا معه في السماويات في المسيح يسوع،","ليظهر في الدهور الآتية غنى نعمته الفائق باللطف علينا في المسيح يسوع.","لأنكم بالنعمة مخلصون، بالإيمان، وذلك ليس منكم. هو عطية االله.","ليس من أعمال كيلا يفتخر أحد.","لأننا نحن عمله، مخلوقين في المسيح يسوع لأعمال صالحة، قد سبق االله فأعدها لكي نسلك فيها.","لذلك اذكروا أنكم أنتم الأمم قبلا في الجسد، المدعوين غرلة من المدعو ختانا مصنوعا باليد في الجسد،","أنكم كنتم في ذلك الوقت بدون مسيح، أجنبيين عن رعوية إسرائيل، وغرباء عن عهود الموعد، لا رجاء لكم وبلا إله في العالم.","ولكن الآن في المسيح يسوع، أنتم الذين كنتم قبلا بعيدين صرتم قريبين بدم المسيح.","لأنه هو سلامنا، الذي جعل الاثنين واحدا، ونقض حائط السياج المتوسط","أي العداوة. مبطلا بجسده ناموس الوصايا في فرائض، لكي يخلق الاثنين في نفسه إنسانا واحدا جديدا، صانعا سلاما،","ويصالح الاثنين في جسد واحد مع االله بالصليب، قاتلا العداوة به.","فجاء وبشركم بسلام، أنتم البعيدين والقريبين.","لأن به لنا كلينا قدوما في روح واحد إلى الآب.","فلستم إذا بعد غرباء ونزلا، بل رعية مع القديسين وأهل بيت االله،","مبنيين على أساس الرسل والأنبياء، ويسوع المسيح نفسه حجر الزاوية،","الذي فيه كل البناء مركبا معا ينمو هيكلا مقدسا في الرب.","الذي فيه أنتم أيضا مبنيون معا، مسكنا لله في الروح."],["بسبب هذا أنا بولس، أسير المسيح يسوع لأجلكم أيها الأمم،","إن كنتم قد سمعتم بتدبير نعمة االله المعطاة لي لأجلكم.","أنه بإعلان عرفني بالسر. كما سبقت فكتبت بالإيجاز.","الذي بحسبه حينما تقرأونه تقدرون أن تفهموا درايتي بسر المسيح.","الذي في أجيال أخر لم يعرف به بنو البشر، كما قد أعلن الآن لرسله القديسين وأنبيائه بالروح:","أن الأمم شركاء في الميراث والجسد ونوال موعده في المسيح بالإنجيل.","الذي صرت أنا خادما له حسب موهبة نعمة االله المعطاة لي حسب فعل قوته.","لي أنا أصغر جميع القديسين أعطيت هذه النعمة، أن أبشر بين الأمم بغنى المسيح الذي لا يستقصى،","وأنير الجميع في ما هو شركة السر المكتوم منذ الدهور في االله خالق الجميع بيسوع المسيح.","لكي يعرف الآن عند الرؤساء والسلاطين في السماويات بواسطة الكنيسة بحكمة االله المتنوعة،","حسب قصد الدهور الذي صنعه في المسيح يسوع ربنا.","الذي به لنا جراءة وقدوم بإيمانه عن ثقة.","لذلك أطلب أن لا تكلوا في شدائدي لأجلكم التي هي مجدكم.","بسبب هذا أحني ركبتي لدى أبي ربنا يسوع المسيح،","الذي منه تسمى كل عشيرة في السماوات وعلى الأرض.","لكي يعطيكم بحسب غنى مجده أن تتأيدوا بالقوة بروحه في الإنسان الباطن،","ليحل المسيح بالإيمان في قلوبكم،","وأنتم متأصلون ومتأسسون في المحبة، حتى تستطيعوا أن تدركوا مع جميع القديسين ما هو العرض والطول والعمق والعلو،","وتعرفوا محبة المسيح الفائقة المعرفة، لكي تمتلئوا إلى كل ملء االله.","والقادر أن يفعل فوق كل شيء أكثر جدا مما نطلب أو نفتكر، بحسب القوة التي تعمل فينا،","له المجد في الكنيسة في المسيح يسوع إلى جميع أجيال دهر الدهور. آمين."],["فأطلب إليكم، أنا الأسير في الرب، أن تسلكوا كما يحق للدعوة التي دعيتم بها.","بكل تواضع، ووداعة، وبطول أناة، محتملين بعضكم بعضا في المحبة.","مجتهدين أن تحفظوا وحدانية الروح برباط السلام.","جسد واحد، وروح واحد، كما دعيتم أيضا في رجاء دعوتكم الواحد.","رب واحد، إيمان واحد، معمودية واحدة،","إله وآب واحد للكل، الذي على الكل وبالكل وفي كلكم.","ولكن لكل واحد منا أعطيت النعمة حسب قياس هبة المسيح.","لذلك يقول: »إذ صعد إلى العلاء سبى سبيا وأعطى الناس عطايا«.","وأما أنه صعد، فما هو إلا إنه نزل أيضا أولا إلى أقسام الأرض السفلى.","الذي نزل هو الذي صعد أيضا فوق جميع السماوات، لكي يملأ الكل.","وهو أعطى البعض أن يكونوا رسلا، والبعض أنبياء، والبعض مبشرين، والبعض رعاة ومعلمين،","لأجل تكميل القديسين، لعمل الخدمة، لبنيان جسد المسيح،","إلى أن ننتهي جميعنا إلى وحدانية الإيمان ومعرفة ابن االله. إلى إنسان كامل. إلى قياس قامة ملء المسيح.","كي لا نكون في ما بعد أطفالا مضطربين ومحمولين بكل ريح تعليم، بحيلة الناس، بمكر إلى مكيدة الضلال.","بل صادقين في المحبة، ننمو في كل شيء إلى ذاك الذي هو الرأس: المسيح،","الذي منه كل الجسد مركبا معا، ومقترنا بمؤازرة كل مفصل، حسب عمل، على قياس كل جزء، يحصل نمو الجسد لبنيانه في المحبة.","فأقول هذا وأشهد في الرب، أن لا تسلكوا في ما بعد كما يسلك سائر الأمم أيضا ببطل ذهنهم،","إذ هم مظلمو الفكر، ومتجنبون عن حياة االله لسبب الجهل الذي فيهم بسبب غلاظة قلوبهم.","الذين إذ هم قد فقدوا الحس، أسلموا نفوسهم للدعارة ليعملوا كل نجاسة في الطمع.","وأما أنتم فلم تتعلموا المسيح هكذا -","إن كنتم قد سمعتموه وعلمتم فيه كما هو حق في يسوع،","أن تخلعوا من جهة التصرف السابق الإنسان العتيق الفاسد بحسب شهوات الغرور،","وتتجددوا بروح ذهنكم،","وتلبسوا الإنسان الجديد المخلوق بحسب االله في البر وقداسة الحق.","لذلك اطرحوا عنكم الكذب وتكلموا بالصدق كل واحد مع قريبه، لأننا بعضنا أعضاء البعض.","اغضبوا ولا تخطئوا. لا تغرب الشمس على غيظكم","ولا تعطوا إبليس مكانا.","لا يسرق السارق في ما بعد، بل بالحري يتعب عاملا الصالح بيديه، ليكون له أن يعطي من له احتياج.","لا تخرج كلمة ردية من أفواهكم، بل كل ما كان صالحا للبنيان، حسب الحاجة، كي يعطي نعمة للسامعين.","ولا تحزنوا روح االله القدوس الذي به ختمتم ليوم الفداء.","ليرفع من بينكم كل مرارة وسخط وغضب وصياح وتجديف مع كل خبث.","وكونوا لطفاء بعضكم نحو بعض، شفوقين متسامحين كما سامحكم االله أيضا في المسيح."],["فكونوا متمثلين باالله كأولاد أحباء،","واسلكوا في المحبة كما أحبنا المسيح أيضا وأسلم نفسه لأجلنا، قربانا وذبيحة لله رائحة طيبة.","وأما الزنا وكل نجاسة أو طمع فلا يسم بينكم كما يليق بقديسين،","ولا القباحة، ولا كلام السفاهة والهزل التي لا تليق، بل بالحري الشكر.","فإنكم تعلمون هذا أن كل زان أو نجس أو طماع، الذي هو عابد للأوثان ليس له ميراث في ملكوت المسيح واالله.","لا يغركم أحد بكلام باطل، لأنه بسبب هذه الأمور يأتي غضب االله على أبناء المعصية.","فلا تكونوا شركاءهم.","لأنكم كنتم قبلا ظلمة وأما الآن فنور في الرب. اسلكوا كأولاد نور.","لأن ثمر الروح هو في كل صلاح وبر وحق.","مختبرين ما هو مرضي عند الرب.","ولا تشتركوا في أعمال الظلمة غير المثمرة بل بالحري وبخوها.","لأن الأمور الحادثة منهم سرا ذكرها أيضا قبيح.","ولكن الكل إذا توبخ يظهر بالنور. لأن كل ما أظهر فهو نور.","لذلك يقول: »استيقظ أيها النائم وقم من الأموات فيضيء لك المسيح«.","فانظروا كيف تسلكون بالتدقيق، لا كجهلاء بل كحكماء،","مفتدين الوقت لأن الأيام شريرة.","من أجل ذلك لا تكونوا أغبياء بل فاهمين ما هي مشيئة الرب.","ولا تسكروا بالخمر الذي فيه الخلاعة، بل امتلئوا بالروح،","مكلمين بعضكم بعضا بمزامير وتسابيح وأغاني روحية، مترنمين ومرتلين في قلوبكم للرب.","شاكرين كل حين على كل شيء في اسم ربنا يسوع المسيح، لله والآب.","خاضعين بعضكم لبعض في خوف االله.","أيها النساء اخضعن لرجالكن كما للرب،","لأن الرجل هو رأس المرأة كما أن المسيح أيضا رأس الكنيسة، وهو مخلص الجسد.","ولكن كما تخضع الكنيسة للمسيح، كذلك النساء لرجالهن في كل شيء.","أيها الرجال، أحبوا نساءكم كما أحب المسيح أيضا الكنيسة وأسلم نفسه لأجلها،","لكي يقدسها، مطهرا إياها بغسل الماء بالكلمة،","لكي يحضرها لنفسه كنيسة مجيدة، لا دنس فيها ولا غضن أو شيء من مثل ذلك، بل تكون مقدسة وبلا عيب.","كذلك يجب على الرجال أن يحبوا نساءهم كأجسادهم. من يحب امرأته يحب نفسه.","فإنه لم يبغض أحد جسده قط بل يقوته ويربيه، كما الرب أيضا للكنيسة.","لأننا أعضاء جسمه، من لحمه ومن عظامه.","من أجل هذا يترك الرجل أباه وأمه ويلتصق بامرأته، ويكون الاثنان جسدا واحدا.","هذا السر عظيم، ولكنني أنا أقول من نحو المسيح والكنيسة.","وأما أنتم الأفراد، فليحب كل واحد امرأته هكذا كنفسه، وأما المرأة فلتهب رجلها."],["أيها الأولاد، أطيعوا والديكم في الرب لأن هذا حق.","أكرم أباك وأمك، التي هي أول وصية بوعد،","لكي يكون لكم خير، وتكونوا طوال الأعمار على الأرض.","وأنتم أيها الآباء، لا تغيظوا أولادكم، بل ربوهم بتأديب الرب وإنذاره.","أيها العبيد، أطيعوا سادتكم حسب الجسد بخوف ورعدة، في بساطة قلوبكم كما للمسيح -","لا بخدمة العين كمن يرضي الناس، بل كعبيد المسيح، عاملين مشيئة االله من القلب،","خادمين بنية صالحة كما للرب، ليس للناس.","عالمين أن مهما عمل كل واحد من الخير فذلك يناله من الرب، عبدا كان أم حرا.","وأنتم أيها السادة، افعلوا لهم هذه الأمور، تاركين التهديد، عالمين أن سيدكم أنتم أيضا في السماوات، وليس عنده محاباة.","أخيرا يا إخوتي تقووا في الرب وفي شدة قوته.","البسوا سلاح االله الكامل لكي تقدروا أن تثبتوا ضد مكايد إبليس.","فإن مصارعتنا ليست مع دم ولحم، بل مع الرؤساء، مع السلاطين، مع ولاة العالم، على ظلمة هذا الدهر، مع أجناد الشر الروحية في السماويات.","من أجل ذلك احملوا سلاح االله الكامل لكي تقدروا أن تقاوموا في اليوم الشرير، وبعد أن تتمموا كل شيء أن تثبتوا.","فاثبتوا ممنطقين أحقاءكم بالحق، ولابسين درع البر،","وحاذين أرجلكم باستعداد إنجيل السلام.","حاملين فوق الكل ترس الإيمان، الذي به تقدرون أن تطفئوا جميع سهام الشرير الملتهبة.","وخذوا خوذة الخلاص، وسيف الروح الذي هو كلمة االله.","مصلين بكل صلاة وطلبة كل وقت في الروح، وساهرين لهذا بعينه بكل مواظبة وطلبة، لأجل جميع القديسين،","ولأجلي، لكي يعطى لي كلام عند افتتاح فمي، لأعلم جهارا بسر الإنجيل،","الذي لأجله أنا سفير في سلاسل، لكي أجاهر فيه كما يجب أن أتكلم.","ولكن لكي تعلموا أنتم أيضا أحوالي، ماذا أفعل، يعرفكم بكل شيء تيخيكس الأخ الحبيب والخادم الأمين في الرب،","الذي أرسلته إليكم لهذا بعينه لكي تعلموا أحوالنا، ولكي يعزي قلوبكم.","سلام على الإخوة، ومحبة بإيمان من االله الآب والرب يسوع المسيح.","النعمة مع جميع الذين يحبون ربنا يسوع المسيح في عدم فساد. آمين. )كتبت إلى أهل أفسس من رومية على يد تيخيكس( رسالة بولس الرسول إلى أهل فيلبي"]];
